/* بيانات قسم mawdui: تُحمَّل عند أول فتح للقسم */
window.MAWDUI = [{"id":"tawhid","t":"التوحيد","ic":"i-tawhid","d":"أصل الدين وأعظم موضوعات القرآن: إثبات الوحدانية، ومعرفة الله بأسمائه وصفاته، ونفي الشرك، وإخلاص العمل والتوكل.","tp":[{"id":"wahdaniyya","t":"إثبات وحدانية الله","d":"الله واحد لا شريك له في ذاته ولا صفاته ولا أفعاله ولا عبادته؛ وهذه هي كلمة التوحيد التي دار عليها القرآن كله.","r":[[112,1,4],[2,163,163],[3,18,18],[21,22,22]],"q":[["tabari",112,1,"ترجيح","فإذا كان ذلك كذلك، فالذي هو أولى بتأويل الكلمة، المعنى المعروف من كلام من نزل القرآن بلسانه؛ ولو كان حديث ابن بُريدة، عن أبيه صحيحا، كان أولى الأقوال بالصحة، لأن رسول الله ﷺ أعلم بما عنى الله جل ثناؤه، وبما أنزل عليه."],["qurtubi",112,1,"نظر واستنباط","قُلْتُ: قَدْ أَتَيْنَا عَلَى هَذِهِ الْأَقْوَالِ مُبَيَّنَةً فِي الصَّمَدِ، فِي (كِتَابِ الْأَسْنَى) وَأَنَّ الصَّحِيحَ مِنْهَا. مَا شَهِدَ لَهُ الِاشْتِقَاقُ، وَهُوَ الْقَوْلُ الْأَوَّلُ، ذَكَرَهُ الْخَطَّابِيُّ. وَقَدْ أَسْقَطَ مِنْ هَذِهِ السُّورَةِ مَنْ أَبْعَدَهُ اللَّهُ وَأَخْزَاهُ، وَجَعَلَ النَّارَ مَقَامَهُ وَمَثْوَاهُ، وَقَرَأَ اللَّهُ الْوَاحِدُ الصَّمَدُ فِي الصَّلَاةِ، وَالنَّاسُ يَسْتَمِعُونَ، فَأَسْقَطَ: قُلْ هُوَ، وَزَعَمَ أَنَّهُ لَيْسَ مِنَ الْقُرْآنِ. وَغَيَّرَ لَفْظَ أَحَدٌ، وأدعى أن هذا هُوَ الصَّوَابُ، وَالَّذِي عَلَيْهِ النَّاسُ هُوَ الْبَاطِلُ وَالْمُحَالُ، فَأَبْطَلَ مَعْنَى الْآيَةِ، لِأَنَّ أَهْلَ التَّفْسِيرِ قَالُوا: نَزَلَتِ الْآيَةُ جَوَابًا لِأَهْلِ الشِّرْكِ لَمَّا قَالُوا لِرَسُولِ اللَّهِ ﷺ: صِفْ لَنَا رَبّكَ، أَمِنْ ذَهَبٍ هُوَ أَمْ مِنْ نُحَاسٍ أَمْ مِنْ صُفْرٍ؟"]],"l":[["saadi",2,163,"لطيفة واستنباط","ففي هذه الآية إثبات وحدانية الباري وإلهيته وتقريرها بنفيها عن غيره من المخلوقين وبيان أصل الدليل على ذلك وهو إثبات رحمته التي من آثارها وجود جميع النعم واندفاع جميع النقم، فهذا دليل إجمالي على وحدانيته تعالى."],["saadi",3,18,"لطيفة واستنباط","وفي هذه الآية فضيلة العلم والعلماء لأن الله خصهم بالذكر من دون البشر، وقرن شهادتهم بشهادته وشهادة ملائكته وجعل شهادتهم من أكبر الأدلة والبراهين على توحيده ودينه وجزائه، وأنه يجب على المكلفين قبول هذه الشهادة العادلة الصادقة، وفي ضمن ذلك تعديلهم وأن الخلق تبع لهم وأنهم هم الأئمة والمتبوعون، وفي هذا من الفضل والشرف وعلو المكانة ما لا يقادر قدره."],["saadi",21,22,"لطيفة واستنباط","وبيانُ ذلك: أنَّ العالم العلويَّ والسفليَّ على ما يُرى في أكمل ما يكون من الصَّلاح والانتظام، الذي ما فيه خللٌ ولا عيبٌ ولا ممانعةٌ ولا معارضةٌ، فدلَّ ذلك على أن مدبِّره واحدٌ وربَّه واحدٌ وإلهه واحدٌ؛ فلو كان له مدبِّران وربَّان أو أكثر من ذلك؛ لاختلَّ نظامُه وتقوَّضت أركانُه؛ فإنهما يتمانعان ويتعارضان، وإذا أراد أحدُهما تدبير شيء وأراد الآخر عدمه؛ فإنَّه محالٌ وجود مرادهما معاً، ووجود مراد أحدِهِما دونَ الآخر يدلُّ على عَجْزِ الآخر وعدم اقتدارِهِ، واتفاقُهما على مرادٍ واحدٍ في جميع الأمور غيرُ ممكنٍ"]]},{"id":"asma","t":"أسماء الله وصفاته","d":"يعرّفنا القرآن بربنا بأسمائه الحسنى وصفاته العلى، ويأمرنا أن ندعوه بها، وأن نثبتها كما وردت دون تمثيل ولا تعطيل.","r":[[59,22,24],[2,255,255],[42,11,11],[7,180,180],[17,110,110],[20,8,8]],"q":[["qurtubi",7,180,"استنباط","الثَّالِثَةُ- وَاخْتَلَفَ الْعُلَمَاءُ مِنْ هَذَا الْبَابِ فِي الِاسْمِ وَالْمُسَمَّى، وَقَدْ ذَكَرْنَا مَا لِلْعُلَمَاءِ مِنْ ذَلِكَ فِي \"الْكِتَابِ الْأَسْنَى\". قَالَ ابْنُ الْحَصَّارِ: وَفِي هَذِهِ الْآيَةِ وُقُوعُ الِاسْمِ عَلَى الْمُسَمَّى وَوُقُوعُهُ عَلَى التَّسْمِيَةِ. فَقَوْلُهُ: \"وَلِلَّهِ\" وَقَعَ عَلَى الْمُسَمَّى، وَقَوْلُهُ: \"الْأَسْماءُ\" وَهُوَ جَمْعُ اسْمٍ وَاقِعٌ عَلَى التَّسْمِيَاتِ. يَدُلُّ عَلَى صِحَّةِ مَا قُلْنَاهُ قَوْلُهُ: \"فَادْعُوهُ بِها ١٨٠\"، وَالْهَاءُ فِي قَوْلِهِ: \"فَادْعُوهُ ١٨٠\" تَعُودُ عَلَى الْمُسَمَّى سُبْحَانَهُ وَتَعَالَى، فَهُوَ الْمَدْعُوُّ. وَالْهَاءُ فِي قَوْلِهِ \"بِها\" تَعُودُ عَلَى الْأَسْمَاءِ، وهي التسميات التي يدعى بلا بِغَيْرِهَا. هَذَا الَّذِي يَقْتَضِيهِ لِسَانُ الْعَرَبِ."],["tabari",20,8,"ترجيح","والصواب من القول في ذلك، قول من قال: معناه: يعلم السرّ وأخفى من السرّ، لأن ذلك هو الظاهر من الكلام؛ ولو كان معنى ذلك ما تأوّله ابن زيد، لكان الكلام: وأخفى الله سرّه، لأن أخفى: فعل واقع متعدّ، إذ كان بمعنى فعل على ما تأوّله ابن زيد، وفي انفراد أخفى من مفعوله، والذي يعمل فيه لو كان بمعنى فعل الدليل الواضح على أنه بمعنى أفعل. وأن تأويل الكلام: فإنه يعلم السرّ وأخفى منه. فإذا كان ذلك تأويله، فالصواب من القول في معنى أخفى من السرّ أن يقال: هو ما علم الله مما أخفى عن العباد، ولم يعلموه مما هو كائن ولم يكن، لأن ما ظهر وكان فغير سرّ، وأن ما لم يكن وهو غير كائن فلا شيء، وأن ما لم يكن وهو كائن فهو أخفى من السرّ، لأن ذلك لا يعلمه إلا الله، ثم من أعلمه ذلك من عباده."]],"l":[["saadi",42,11,"لطيفة واستنباط","وهذه الآية ونحوها دليلٌ لمذهب أهل السنة والجماعة من إثبات الصفاتِ ونفي مماثلة المخلوقات، وفيها ردٌّ على المشبِّهة في قوله:{ليس كمثلِهِ شيءٌ}، وعلى المعطِّلة في قوله:{وهو السميعُ البصيرُ}."]]},{"id":"rububiyya","t":"براهين الربوبية في الخلق","d":"يستدل القرآن على وحدانية الله بآياته في الخلق: السماء والأرض، والليل والنهار، والمطر والنبات، فمن خلق ودبّر استحق أن يُعبد وحده.","r":[[2,21,22],[2,164,164],[6,95,99]],"q":[["tabari",2,164,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك، أنّ الله تعالى ذكره نَبَّه عباده = على الدلالة على وَحدانيته وتفرده بالألوهية، دون كل ما سواه من الأشياء = بهذه الآية. وجائزٌ أن تكون نزلت فيما قاله عطاء، وجائزٌ أن تكون فيما قاله سعيد بن جبير وأبو الضحى، ولا خبرَ عندنا بتصحيح قول أحد الفريقين يقطع العذرَ، فيجوز أن يقضيَ أحدٌ لأحد الفريقين بصحة قولٍ على الآخر. وأيُّ القولين كان صحيحًا، فالمراد من الآية ما قلت."],["qurtubi",2,164,"استنباط","الرَّابِعَةُ- هَذِهِ الْآيَةُ وَمَا كَانَ مِثْلُهَا دَلِيلٌ عَلَى جَوَازِ رُكُوبِ الْبَحْرِ مُطْلَقًا لِتِجَارَةٍ كَانَ أَوْ عِبَادَةٍ، كَالْحَجِّ وَالْجِهَادِ. وَمِنَ السُّنَّةِ حَدِيثُ أَبِي هُرَيْرَةَ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنَ الْمَاءِ. الْحَدِيثُ. وَحَدِيثُ أَنَسِ بْنِ مَالِكٍ فِي قِصَّةِ أُمِّ حَرَامٍ، أَخْرَجَهُمَا الْأَئِمَّةُ: مَالِكٌ وَغَيْرُهُ. رَوَى حَدِيثَ أَنَسٍ عَنْهُ جَمَاعَةٌ عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ عَنْ أَنَسٍ، وَرَوَاهُ بِشْرُ بْنُ عُمَرَ عَنْ مَالِكٍ عَنْ إِسْحَاقَ عَنْ أَنَسٍ عَنْ أُمِّ حَرَامٍ، جَعَلَهُ مِنْ مُسْنَدِ أُمِّ حَرَامٍ لَا مِنْ مُسْنَدِ أَنَسٍ."],["tabari",6,96,"ترجيح","قال أبو جعفر: وأولى القولين في تأويل ذلك عندي بالصواب، تأويل من تأوَّله: وجعل الشمس والقمرَ يجريان بحساب وعددٍ لبلوغ أمرهما ونهاية آجالهما، ويدوران لمصالح الخلق التي جُعِلا لها."]],"l":[["saadi",2,164,"لطيفة واستنباط","وغاية العبد الضعيف أن جعله الله جزءاً من أجزاء الأسباب التي بها وجدت هذه الأمور العظام، فهذا يدل على رحمة الله وعنايته بخلقه، وذلك يوجب أن تكون المحبة كلها له والخوف والرجاء وجميع الطاعة والذل والتعظيم {وما أنزل الله من السماء من ماء}؛ وهو المطر النازل من السحاب {فأحيا به الأرض بعد موتها}؛ فأظهرت من أنواع الأقوات وأصناف النبات ما هو من ضرورات الخلائق التي لا يعيشون بدونها"],["saadi",6,99,"لطيفة واستنباط","وفي وصفه بأنه متراكبٌ إشارة إلى أنَّ حبوبه متعددة، وجميعها تستمدُّ من مادةٍ واحدةٍ، وهي لا تختلط، بل هي متفرِّقة الحبوب مجتمعة الأصول، وإشارة أيضاً إلى كثرتها وشمول ريعها وغلتها؛ ليبقى أصل البذر، ويبقى بقية كثيرةٌ للأكل والادِّخار."],["saadi",6,99,"لطيفة واستنباط","ولما ذكر عموم ما ينبت بالماء من أنواع الأشجار والنبات؛ ذَكَرَ الزرع والنخل لكثرة نفعهما وكونهما قوتاً لأكثر الناس، فقال:{فأخرجنا منه خَضِراً نخرِجُ منه}؛ أي: من ذلك النبات الخضر {حبًّا متراكباً}: بعضُه فوق بعض من بُرٍّ وشعير وذرة وأرز وغير ذلك من أصناف الزروع، وفي وصفه بأنه متراكبٌ إشارة إلى أنَّ حبوبه متعددة، وجميعها تستمدُّ من مادةٍ واحدةٍ، وهي لا تختلط، بل هي متفرِّقة الحبوب مجتمعة الأصول، وإشارة أيضاً إلى كثرتها وشمول ريعها وغلتها؛ ليبقى أصل البذر، ويبقى بقية كثيرةٌ للأكل والادِّخار."]]},{"id":"shirk","t":"نفي الشرك وخطره","d":"الشرك أعظم الذنوب وأقبحها، لا يغفره الله لمن مات عليه، وهو يحبط العمل ويهدم الأصل الذي تقوم عليه سائر الأعمال.","r":[[4,48,48],[31,13,13],[39,65,66],[6,151,151],[4,116,116],[5,72,72],[22,31,31],[39,3,3]],"q":[["qurtubi",4,48,"استنباط","الثَّالِثَةُ- فَأَمَّا تَزْكِيَةُ الْغَيْرِ وَمَدْحُهُ لَهُ، فَفِي الْبُخَارِيِّ مِنْ حَدِيثِ أَبِي بَكْرَةَ أَنَّ رَجُلًا ذُكِرَ عِنْدَ النَّبِيِّ ﷺ فَأَثْنَى عَلَيْهِ رَجُلٌ خَيْرًا، فَقَالَ النَّبِيُّ ﷺ: (وَيْحَكَ قَطَعْتَ عُنُقَ صَاحِبِكَ- يَقُولُهُ مِرَارًا- إِنْ كَانَ أَحَدُكُمْ مَادِحًا لَا مَحَالَةَ فَلْيَقُلْ أَحْسَبُ كَذَا وَكَذَا إِنْ كَانَ يَرَى أَنَّهُ كَذَلِكَ وَحَسِيبُهُ اللَّهُ وَلَا يُزَكِّي عَلَى اللَّهِ أَحَدًا) فَنَهَى ﷺ أَنْ يُفْرَطَ فِي مَدْحِ الرَّجُلِ بِمَا لَيْسَ فِيهِ فَيَدْخُلُهُ فِي ذَلِكَ الْإِعْجَابُ وَالْكِبْرُ، وَيَظُنُّ أَنَّهُ فِي الْحَقِيقَةِ بِتِلْكَ الْمَنْزِلَةِ فَيَحْمِلُهُ، ذَلِكَ عَلَى تَضْيِيعِ الْعَمَلِ وَتَرْكِ الِازْدِيَادِ مِنَ الْفَضْلِ، وَلِذَلِكَ قَالَ ﷺ: (وَيْحَكَ قَطَعْتَ عُنُقَ صَاحِبِكَ)."]],"l":[["saadi",4,116,"لطيفة واستنباط","ويدلُّ على ذلك قوله تعالى:{كنتُم خير أمةٍ أخۡرِجَتۡ للناس تأمرون بالمعروفِ وتَنۡهَوۡنَ عن المنكرِ}، ووجهُ الدِّلالة منها أنَّ الله تعالى أخبر أن المؤمنين من هذه الأمة لا يأمُرون إلا بالمعروف؛ فإذا اتَّفقوا على إيجاب شيءٍ أو استحبابِهِ؛ فهو مما أمروا به، فيتعيَّن بنصِّ الآية أن يكون معروفاً، ولا شيء بعد المعروف غير المنكر، وكذلك إذا اتَّفقوا على النهي عن شيء؛ فهو مما نهوا عنه، فلا يكون إلاَّ منكراً."]]},{"id":"tawakkul","t":"الإخلاص والتوكل","d":"الإخلاص أن يكون العمل لله وحده، والتوكل صدق الاعتماد على الله مع الأخذ بالأسباب، وبهما تتحقق العبودية.","r":[[98,5,5],[39,2,3],[65,2,3],[3,173,174],[8,2,4],[9,129,129],[25,58,58],[14,11,12],[3,159,159],[67,29,29],[5,23,23]],"q":[["tabari",65,2,"ترجيح","والصواب من القول في ذلك عندي قول من قال: عنى بالفاحشة في هذا الموضع: المعصية، وذلك أن الفاحشة هي كلّ أمر قبيح تعدّى فيه حدّه، فالزنى من ذلك، والسرق والبذاء على الأحماء، وخروجها متحوّلة عن منزلها الذي يلزمها أن تعتدّ فيه منه، فأي ذلك فعلت وهي في عدتها، فلزوجها إخراجها من بيتها ذلك، لإتيانها بالفاحشة التي ركبتها."],["qurtubi",3,159,"استنباط","الرابعة- جَاءَ فِي مُصَنَّفِ أَبِي دَاوُدَ عَنْ أَبِي هُرَيْرَةَ قَالَ قَالَ رَسُولُ اللَّهِ ﷺ: (الْمُسْتَشَارُ مُؤْتَمَنٌ). قَالَ الْعُلَمَاءُ: وَصِفَةُ المستشار إن كان في الأحكام أن يَكُونَ عَالِمًا دَيِّنًا، وَقَلَّمَا يَكُونُ ذَلِكَ إِلَّا فِي عَاقِلٍ. قَالَ الْحَسَنُ: مَا كَمُلَ دِينُ امْرِئٍ مَا لَمْ يَكْمُلْ عَقْلُهُ. فَإِذَا اسْتُشِيرَ مَنْ هَذِهِ صِفَتُهُ وَاجْتَهَدَ فِي الصَّلَاحِ وَبَذَلَ جَهْدَهُ فَوَقَعَتِ الْإِشَارَةُ خَطَأً فَلَا غَرَامَةَ عَلَيْهِ، قَالَهُ الْخَطَّابِيُّ وَغَيْرُهُ. الْخَامِسَةُ- وَصِفَةُ الْمُسْتَشَارِ فِي أُمُورِ الدُّنْيَا أَنْ يَكُونَ عَاقِلًا مُجَرِّبًا وَادًّا فِي الْمُسْتَشِيرِ. قَالَ:"],["qurtubi",3,159,"استنباط","السَّادِسَةُ- وَالشُّورَى مَبْنِيَّةٌ عَلَى اخْتِلَافِ الْآرَاءِ، وَالْمُسْتَشِيرُ يَنْظُرُ فِي ذَلِكَ الْخِلَافِ، وَيَنْظُرُ أَقْرَبَهَا قَوْلًا إِلَى الْكِتَابِ وَالسُّنَّةِ إِنْ أَمْكَنَهُ، فَإِذَا أَرْشَدَهُ اللَّهُ تَعَالَى إِلَى مَا شَاءَ مِنْهُ عَزَمَ عَلَيْهِ وَأَنْفَذَهُ مُتَوَكِّلًا عَلَيْهِ، إِذْ هَذِهِ غَايَةُ الِاجْتِهَادِ الْمَطْلُوبِ، وَبِهَذَا أَمَرَ اللَّهُ تَعَالَى نَبِيَّهُ فِي هَذِهِ الْآيَةِ. السَّابِعَةُ- قَوْلُهُ تَعَالَى: ﴿فَإِذا عَزَمْتَ فَتَوَكَّلْ عَلَى اللَّهِ﴾ قَالَ قَتَادَةُ: أَمَرَ اللَّهُ تَعَالَى نَبِيَّهُ عَلَيْهِ السَّلَامُ إِذَا عَزَمَ عَلَى أَمْرٍ أَنْ يَمْضِيَ فِيهِ وَيَتَوَكَّلَ عَلَى اللَّهِ، لَا عَلَى مُشَاوَرَتِهِمْ."]],"l":[["saadi",14,11,"لطيفة واستنباط","وفي هذا كالإشارة من الرسل عليهم الصلاة والسلام لقومهم بآيةٍ عظيمةٍ، وهو أنَّ قومهم في الغالب أنَّ لهم القهر والغلبة عليهم، فتحدَّتهم رسلُهم بأنَّهم متوكِّلون على الله في دفع كيدهم ومكرهم، وجازمون بكفايته إيَّاهم، وقد كفاهم الله شرَّهم مع حرصهم على إتلافهم وإطفاء ما معهم من الحقِّ، فيكون هذا كقول نوح لقومِهِ:{يا قوم إن كان كَبُرَ عليكم مقامي وتذكيري بآيات الله فعلى الله توكَّلۡتُ فأجمِعوا أمرَكم وشُركاءَكم ثمَّ لا يكنۡ أمرُكم عليكم غُمَّة ثم اقضوا إليَّ ولا تُنظِرونِ ."],["saadi",5,23,"لطيفة واستنباط","وفي هذا دليل على أن العقوبة على الذنب قد تكون بزوال نعمةٍ موجودةٍ أو دفع نعمةٍ قد انعقد سببُ وجودِها، أو تأخُّرها إلى وقت آخر، ولعل الحكمة في هذه المدة أن يموت أكثر هؤلاء الذين قالوا هذه المقالة الصادرة عن قلوب لا صَبْرَ فيها ولا ثباتَ، بل قد ألفت الاستعباد لعدُوِّها ولم تكن لها هممٌ ترقِّيها إلى ما فيه ارتقاؤها وعلوُّها، ولتظهر ناشئةٌ جديدةٌ تتربَّى عقولهم على طلبِ قهرِ الأعداء وعدم الاستعباد والذُّلِّ المانع من السعادة."]]}]},{"id":"akhlaq","t":"الأخلاق","ic":"i-flower","d":"منظومة الفضائل التي أمر بها القرآن: صدق وأمانة، وصبر وعدل، ورحمة وعفو، وتواضع وبر.","tp":[{"id":"sidq","t":"الصدق والأمانة","d":"الصدق في القول والعمل والوعد، وأداء الأمانات إلى أهلها، من أخص صفات المؤمنين وأقوى أسس الثقة في المجتمع.","r":[[9,119,119],[33,70,71],[4,58,58],[23,8,8],[33,23,24],[39,33,35]],"q":[["qurtubi",23,8,"نظر واستنباط","قُلْتُ: فِيهِ نَظَرٌ، مَا لَمْ يَكُنْ جَاهِلًا أَوْ مُتَأَوِّلًا، وَإِنْ كَانَ الْإِجْمَاعُ مُنْعَقِدًا عَلَى أَنَّ قَوْلِهِ تَعَالَى: \"وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حافِظُونَ. إِلَّا عَلى أَزْواجِهِمْ أَوْ مَا مَلَكَتْ أَيْمانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ\" خُصَّ بِهِ الرِّجَالُ دُونَ النِّسَاءِ، فَقَدْ رَوَى مَعْمَرٌ عَنْ قَتَادَةَ قَالَ: تَسَرَّرَتِ امْرَأَةٌ غُلَامَهَا، فَذُكِرَ ذَلِكَ لِعُمَرَ فَسَأَلَهَا: مَا حَمَلَكِ عَلَى ذَلِكَ؟ قَالَتْ: كُنْتُ أَرَاهُ يَحِلُّ لِي بِمِلْكِ يَمِينِي كَمَا يَحِلُّ لِلرَّجُلِ الْمَرْأَةُ بِمِلْكِ الْيَمِينِ، فَاسْتَشَارَ عُمَرُ فِي رَجْمِهَا أَصْحَابِ رَسُولِ اللَّهِ ﷺ فَقَالُوا: تَأَوَّلَتْ كِتَابَ اللَّهِ عَزَّ وَجَلَّ عَلَى غَيْرِ تَأْوِيلِهِ: لَا رَجْمَ عَلَيْهَا. فَقَالَ عُمَرُ: لَا جَرَمَ! وَاللَّهِ لَا أُحِلُّكِ لِحُرٍّ بَعْدَهُ أبدا."],["tabari",39,33,"ترجيح","والصواب من القول في ذلك أن يقال: إن الله تعالى ذكره عنى بقوله: ﴿وَالَّذِي جَاءَ بِالصِّدْقِ وَصَدَّقَ بِهِ﴾ كلّ من دعا إلى توحيد الله، وتصديق رسله، والعمل بما ابتعث به رسوله من بين رسل الله وأتباعه والمؤمنين به، وأن يقال: الصدق هو القرآن، وشهادة أن لا إله إلا الله، والمصدّق به: المؤمنون بالقرآن، من جميع خلق الله كائنا من كان من نبيّ الله وأتباعه."],["qurtubi",23,8,"استنباط","الرَّابِعَةُ- قَوْلُهُ تَعَالَى: ﴿وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حافِظُونَ﴾ قَالَ ابْنُ الْعَرَبِيِّ: \"مِنْ غَرِيبِ الْقُرْآنِ أَنَّ هَذِهِ الْآيَاتِ الْعَشْرَ عَامَّةٌ فِي الرِّجَالِ وَالنِّسَاءِ، كَسَائِرِ أَلْفَاظِ الْقُرْآنِ الَّتِي هِيَ مُحْتَمِلَةٌ لَهُمْ فَإِنَّهَا عَامَّةٌ فِيهِمْ، إِلَّا قوله\" وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حافِظُونَ \"فَإِنَّمَا خَاطَبَ بِهَا الرجال خاصة دون الزوجات، بدليل قوله:\" إِلَّا عَلى أَزْواجِهِمْ أَوْ مَا مَلَكَتْ أَيْمانُهُمْ\". وَإِنَّمَا عُرِفَ حِفْظُ الْمَرْأَةِ فَرْجَهَا مِنْ أَدِلَّةٍ أخرى كَآيَاتِ الْإِحْصَانِ عُمُومًا وَخُصُوصًا وَغَيْرِ ذَلِكَ مِنَ الْأَدِلَّةِ\"."]],"l":[["saadi",33,23,"لطيفة واستنباط","وكانت هذه الطائفة من أهل الكتاب هم بنو قريظةَ من اليهود في قريةٍ خارج المدينة غير بعيد، وكان النبي - صلى الله عليه وسلم - حين هاجر إلى المدينة وادَعَهم وهادَنَهم فلم يقاتلهم ولم يقاتِلوه، وهم باقون على دينهم، لم يغيِّر عليهم شيئاً، فلما رأوا يوم الخندق الأحزاب الذين تحزَّبوا على رسول الله وكَثْرتَهم وقلَّةَ المسلمين، وظنُّوا أنهم سيستأصلون الرسول والمؤمنين، وساعد على ذلك تدجيلُ بعض رؤسائهم عليهم، فنقضوا العهدَ الذي بينهم وبين رسول الله - صلى الله عليه وسلم -، ومالؤوا المشركين على قتاله، فلما خَذَلَ الله المشركين؛ تفرَّغ رسول الله - صلى الله عليه وسلم - لقتالهم، فحاصرهم في حصنهم"]]},{"id":"sabr","t":"الصبر","d":"الصبر على الطاعة وعن المعصية وعلى أقدار الله المؤلمة؛ وقد جعله القرآن عوناً على كل أمر، ووعد الصابرين بأجر بغير حساب.","r":[[2,153,157],[39,10,10],[3,200,200],[103,1,3],[3,186,186],[16,126,128],[42,43,43],[2,45,46],[8,46,46],[31,17,17],[11,115,115],[12,18,18],[12,83,83],[18,67,69],[16,96,97]],"q":[["qurtubi",2,156,"استنباط","الرَّابِعَةُ- قَوْلُهُ تَعَالَى: ﴿قالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ راجِعُونَ﴾ جَعَلَ اللَّهُ تَعَالَى هَذِهِ الْكَلِمَاتِ مَلْجَأً لِذَوِي الْمَصَائِبِ، وَعِصْمَةً لِلْمُمْتَحَنِينَ: لِمَا جَمَعَتْ مِنَ الْمَعَانِي الْمُبَارَكَةِ، فَإِنَّ قَوْلَهُ: \"إِنَّا لِلَّهِ\" تَوْحِيدٌ وَإِقْرَارٌ بِالْعُبُودِيَّةِ وَالْمُلْكِ. وَقَوْلُهُ: \"وَإِنَّا إِلَيْهِ راجِعُونَ\" إِقْرَارٌ بِالْهَلْكِ، عَلَى أَنْفُسِنَا وَالْبَعْثِ مِنْ قُبُورِنَا، وَالْيَقِينُ أَنَّ رُجُوعَ الْأَمْرِ كُلِّهِ إِلَيْهِ كَمَا هُوَ لَهُ. قَالَ سَعِيدُ ابن جُبَيْرٍ رَحِمَهُ اللَّهُ تَعَالَى: لَمْ تُعْطَ هَذِهِ الْكَلِمَاتُ نَبِيًّا قَبْلَ نَبِيِّنَا، وَلَوْ عَرَفَهَا يَعْقُوبُ لَمَا قَالَ: يَا أَسَفَى عَلَى يُوسُفَ."],["tabari",103,1,"ترجيح","والصواب من القول في ذلك: أن يقال: إن ربنا أقسم بالعصر ﴿وَالْعَصْرِ﴾ اسم للدهر، وهو العشيّ والليل والنهار، ولم يخصص مما شمله هذا الاسم معنى دون معنى، فكلّ ما لزِمه هذا الاسم، فداخل فيما أقسم به جلّ ثناؤه."],["qurtubi",42,43,"استنباط","الثَّانِيَةُ- قَوْلُهُ تَعَالَى: ﴿وَجَزاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُها﴾ قَالَ الْعُلَمَاءُ: جَعَلَ اللَّهُ الْمُؤْمِنِينَ صِنْفَيْنِ، صِنْفٌ يَعْفُونَ عَنِ الظَّالِمِ فَبَدَأَ بِذِكْرِهِمْ فِي قَوْلِهِ \"وَإِذا ما غَضِبُوا هُمْ يَغْفِرُونَ\".] الشورى: ٣٧]. وَصِنْفٌ يَنْتَصِرُونَ مِنْ ظَالِمِهِمْ. ثُمَّ بَيَّنَ حَدَّ الِانْتِصَارِ بِقَوْلِهِ: \"وَجَزاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُها\" فَيَنْتَصِرُ مِمَّنْ ظَلَمَهُ مِنْ غَيْرِ أَنْ يَعْتَدِيَ. قَالَ مُقَاتِلٌ وَهِشَامُ بْنُ حُجَيْرٍ: هَذَا فِي الْمَجْرُوحِ يَنْتَقِمُ مِنَ الْجَارِحِ بِالْقِصَاصِ دُونَ غَيْرِهِ مِنْ سَبٍّ أَوْ شَتْمٍ. وَقَالَهُ الشَّافِعِيُّ وَأَبُو حَنِيفَةَ وَسُفْيَانُ. قَالَ سُفْيَانُ: وَكَانَ ابْنُ شُبْرُمَةَ يَقُولُ: لَيْسَ بِمَكَّةَ مِثْلُ هِشَامٍ."]],"l":[]},{"id":"adl","t":"العدل والإحسان","d":"أمر القرآن بالعدل مع القريب والبعيد والصديق والعدو، وقرنه بالإحسان الذي هو الزيادة على الحق بالفضل.","r":[[16,90,90],[4,135,135],[5,8,8],[57,25,25],[6,152,152],[16,91,92],[49,9,9],[7,29,29],[60,8,8],[5,42,42]],"q":[["tabari",16,91,"ترجيح","والصواب من القول في ذلك أن يقال: إن الله تعالى أمر في هذه الآية عباده بالوفاء بعهوده التي يجعلونها على أنفسهم، ونهاهم عن نقض الأيمان بعد توكيدها على أنفسهم لآخرين بعقود تكون بينهم بحقّ مما لا يكرهه الله. وجائز أن تكون نزلت في الذين بايعوا رسول الله ﷺ بنهيهم عن نقض بيعتهم حذرا من قلة عدد المسلمين وكثرة عدد المشركين، وأن تكون نزلت في الذين أرادوا الانتقال بحلفهم عن حلفائهم لقلة عددهم في آخرين لكثرة عددهم، وجائز أن تكون في غير ذلك. ولا خبر تَثْبُت به الحجة أنها نزلت في شيء من ذلك دون شيء؛ ولا دلالة في كتاب ولا حجة عقل أيّ ذلك عُنِيَ بها، ولا قول في ذلك أولى بالحق مما قلنا لدلالة ظاهره عليه، وأن الآية كانت قد نزلت لسبب من الأسباب، ويكون الحكم بها عامًّا في كلّ ما كان بمعنى السبب الذي نزلت فيه."],["qurtubi",49,9,"استنباط","الثَّانِيَةُ- قَالَ الْعُلَمَاءُ: لَا تَخْلُو الْفِئَتَانِ مِنَ الْمُسْلِمِينَ فِي اقْتِتَالِهِمَا، إِمَّا أَنْ يَقْتَتِلَا عَلَى سبيل البغي منهما جميعا أولا. فَإِنْ كَانَ الْأَوَّلُ فَالْوَاجِبُ فِي ذَلِكَ أَنْ يُمْشَى بَيْنَهُمَا بِمَا يُصْلِحُ ذَاتَ الْبَيْنِ وَيُثَمِّرُ الْمُكَافَّةَ وَالْمُوَادَعَةَ. فَإِنْ لَمْ يَتَحَاجَزَا وَلَمْ يَصْطَلِحَا وَأَقَامَتَا عَلَى الْبَغْيِ صِيرَ إِلَى مُقَاتَلَتِهِمَا. وَأَمَّا إِنْ كَانَ الثَّانِي وَهُوَ أَنْ تَكُونَ إِحْدَاهُمَا بَاغِيَةً عَلَى الْأُخْرَى، فَالْوَاجِبُ أَنْ تُقَاتَلَ فِئَةُ الْبَغْيِ إِلَى أَنْ تَكُفَّ وَتَتُوبَ، فَإِنْ فَعَلَتْ أُصْلِحَ بَيْنَهَا وَبَيْنَ الْمَبْغِيِّ عَلَيْهَا بِالْقِسْطِ وَالْعَدْلِ."],["tabari",7,29,"ترجيح","قال أبو جعفر: وأولى الأقوال في تأويل ذلك بالصواب، القولُ الذي قاله من قال: معناه: كما بدأكم الله خلقًا بعد أن لم تكونوا شيئًا، تعودون بعد فنائكم خلقًا مثله، يحشركم إلى يوم القيامة = لأن الله تعالى ذكره: أمر نبيه ﷺ أن يُعْلم بما في هذه الآية قومًا مشركين أهلَ جاهلية، لا يؤمنون بالمعاد، ولا يصدِّقون بالقيامة. فأمره أن يدعوهم إلى الإقرار بأن الله باعثهم يوم القيامة، ومثيبُ مَنْ أطاعه، ومعاقبُ مَنْ عصاه. فقال له: قل لهم: أمرَ ربي بالقسط، وأن أقيموا وجوهكم عند كل مسجد، وأن ادعوه مخلصين له الدين، وأن أقرُّوا بأنْ كما بدأكم تعودون = فترك ذكر\"وأن أقروا بأن\". كما ترك ذكر\"أن\" مع\"أقيموا\"، إذ كان فيما ذكر دلالة على ما حذف منه."]],"l":[["saadi",7,29,"لطيفة واستنباط","وفي هذه الآيات دليلٌ على أن الأوامر والنواهي تابعة للحكمة والمصلحة؛ حيث ذكر تعالى أنه لا يُتَصَوَّر أن يأمر بما تستفحشه وتنكره العقول، وأنه لا يأمر إلا بالعدل والإخلاص."],["saadi",7,29,"لطيفة واستنباط","وفيه دليلٌ على أن الهداية بفضل الله ومَنِّه، وأن الضلالة بخذلانه للعبد إذ تولى ـ بجهله وظلمه ـ الشيطانَ، وتسبَّب لنفسه بالضلال، وأن من حسب أنه مهتدٍ وهو ضالٌّ فإنه لا عذر له؛ لأنه متمكِّن من الهدى، وإنما أتاه حسبانه من ظلمه بترك الطريق الموصل إلى الهدى."],["saadi",5,42,"لطيفة واستنباط","ولهذا قال:{وإن تُعۡرِضۡ عنهم فلن يَضُرُّوك شيئاً وإن حكمتَ فاحكُم بينَهم بالقسطِ إنَّ الله يحبُّ المقسِطين}: حتى ولو كانوا ظلمةً وأعداءً؛ فلا يَمْنَعُكَ ذلك من العدل في الحكم بينهم: وفي هذا بيان فضيلة العدل والقسط في الحكم بين الناس، وأنَّ الله تعالى يحبه."]]},{"id":"afw","t":"الرحمة والعفو","d":"كظم الغيظ والعفو والصفح والإحسان إلى المسيء من أعلى مقامات الأخلاق؛ يقلب العداوة ولاءً، ويرفع صاحبه عند الله.","r":[[3,134,134],[42,40,43],[7,199,199],[24,22,22],[41,34,35]],"q":[["qurtubi",42,40,"استنباط","الثَّانِيَةُ- قَوْلُهُ تَعَالَى: ﴿وَجَزاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُها﴾ قَالَ الْعُلَمَاءُ: جَعَلَ اللَّهُ الْمُؤْمِنِينَ صِنْفَيْنِ، صِنْفٌ يَعْفُونَ عَنِ الظَّالِمِ فَبَدَأَ بِذِكْرِهِمْ فِي قَوْلِهِ \"وَإِذا ما غَضِبُوا هُمْ يَغْفِرُونَ\".] الشورى: ٣٧]. وَصِنْفٌ يَنْتَصِرُونَ مِنْ ظَالِمِهِمْ. ثُمَّ بَيَّنَ حَدَّ الِانْتِصَارِ بِقَوْلِهِ: \"وَجَزاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُها\" فَيَنْتَصِرُ مِمَّنْ ظَلَمَهُ مِنْ غَيْرِ أَنْ يَعْتَدِيَ. قَالَ مُقَاتِلٌ وَهِشَامُ بْنُ حُجَيْرٍ: هَذَا فِي الْمَجْرُوحِ يَنْتَقِمُ مِنَ الْجَارِحِ بِالْقِصَاصِ دُونَ غَيْرِهِ مِنْ سَبٍّ أَوْ شَتْمٍ. وَقَالَهُ الشَّافِعِيُّ وَأَبُو حَنِيفَةَ وَسُفْيَانُ. قَالَ سُفْيَانُ: وَكَانَ ابْنُ شُبْرُمَةَ يَقُولُ: لَيْسَ بِمَكَّةَ مِثْلُ هِشَامٍ."],["tabari",42,40,"ترجيح","فعلى قول ابن زيد هذا تأويل الكلام: وجزاء سيئة من المشركين إليك، سيئة مثلها منكم إليهم، وإن عفوتم وأصلحتم في العفو، فأجركم في عفوكم عنهم إلى الله، إنه لا يحب الكافرين؛ وهذا على قوله كقول الله عز وجل ﴿فَمَنِ اعْتَدَى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدَى عَلَيْكُمْ وَاتَّقُوا اللَّهَ﴾ وللذي قال من ذلك وجه. غير أن الصواب عندنا: أن تحمل الآية على الظاهر ما لم ينقله إلى الباطن ما يجب التسليم لها، ولم يثبت حجة في قوله: ﴿وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا﴾ أنه مراد به المشركون دون المسلمين، ولا بأن هذه الآية منسوخة، فنسلم لها بأن ذلك كذلك."],["tabari",7,199,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك أن يقال: إن الله أمر نبيه ﷺ أن يأمر الناس بالعرف =وهو المعروف في كلام العرب، مصدر في معنى: \"المعروف\"."]],"l":[["saadi",3,134,"لطيفة واستنباط","ففي قوله:{أضعافاً مضاعفة}؛ تنبيه على شدة شناعته بكثرته وتنبيه لحكمة تحريمه، وأن تحريم الربا حكمته أن الله منع منه لما فيه من الظلم، وذلك أن الله أوجب إنظار المعسر وبقاء ما في ذمته من غير زيادة، فإلزامه بما فوق ذلك ظلم متضاعف، فيتعين على المؤمن المتقي تركه وعدم قربانه لأن تركه من موجبات التقوى، والفلاح متوقف على التقوى، فلهذا قال:{واتقوا الله لعلكم تفلحون}."],["saadi",3,134,"لطيفة واستنباط","ويدل على ما قلنا أن الله ذكر لفظ التقوى في هذه الآيات ثلاث مرات، مرة مطلقة، وهي قول:{أعدت للمتقين}، ومرتين مقيدتين فقال:{واتقوا الله}{واتقوا النار}."],["saadi",3,134,"لطيفة واستنباط","فقوله تعالى:{يا أيها الذين آمنوا} كل ما في القرآن من قوله تعالى: يا أيها الذين آمنوا افعلوا كذا أو اتركوا كذا يدل على أن الإيمان هو السبب الداعي والموجب لامتثال ذلك الأمر واجتناب ذلك النهي، لأن الإيمان هو التصديق الكامل بما يجب التصديق به المستلزم لأعمال الجوارح، فنهاهم عن أكل الربا أضعافاً مضاعفة، وذلك هو ما اعتاده أهل الجاهلية ومن لا يبالي بالأوامر الشرعية، من أنه إذا حل الدَّين على المعسر ولم يحصل منه شيء، قالوا له إما أن تقضي ما عليك من الدين"]]},{"id":"tawadu","t":"التواضع وحسن القول","d":"خفض الجناح ولين القول وترك السخرية والتجسس والغيبة من آداب المؤمن مع الناس، وهي من صفات عباد الرحمن.","r":[[25,63,63],[31,18,19],[17,37,37],[49,11,12]],"q":[["tabari",31,19,"ترجيح","وأولى الأقوال في ذلك بالصواب قول من قال: معناه: إن أقبح أو أشرّ الأصوات، وذلك نظير قولهم: إذا رأوا وجها قبيحا، أو منظرا شنيعا، ما أنكر وجه فلان، وما أنكر منظره."],["tabari",49,11,"ترجيح","والصواب من القول في ذلك عندي أن يقال: إن الله عمّ بنهيه المؤمنين عن أن يسخر بعضهم من بعض جميع معاني السخرية، فلا يحلّ لمؤمن أن يسخر من مؤمن لا لفقره، ولا لذنب ركبه، ولا لغير ذلك."],["tabari",49,11,"ترجيح","والذي هو أولى الأقوال في تأويل ذلك عندي بالصواب أن يقال: إن الله تعالى ذكره نهى المؤمنين أن يتنابزوا بالألقاب؛ والتنابز بالألقاب: هو دعاء المرء صاحبه بما يكرهه من اسم أو صفة، وعمّ الله بنهية ذلك، ولم يخصص به بعض الألقاب دون بعض، فغير جائز لأحد من المسلمين أن ينبز أخاه باسم يكرهه، أو صفة يكرهها. وإذا كان ذلك كذلك صحت الأقوال التي قالها أهل التأويل في ذلك التي ذكرناها كلها، ولم يكن بعض ذلك أولى بالصواب من بعض، لأن كلّ ذلك مما نهى الله المسلمين أن ينبز بعضهم بعضا."]],"l":[["saadi",25,63,"لطيفة واستنباط","وفي قوله:{إذا مَرُّوا باللغوِ}: إشارة إلى أنهم لا يقصدون حُضورَه ولا سماعَه، ولكن عند المصادفةِ التي من غير قصدٍ يُكْرِمونَ أنفسهم عنه."],["saadi",25,63,"لطيفة واستنباط","وعبوديَّةٌ لألوهيَّتِهِ وعبادتِهِ ورحمتِهِ، وهي عبوديَّةُ أنبيائِهِ وأوليائِهِ، وهي المراد هنا، ولهذا أضافها إلى اسمه الرحمن؛ إشارةً إلى أنَّهم إنَّما وصلوا إلى هذه الحال بسبب رحمته، فَذَكَرَ [أنَّ] صفاتِهِم أكملُ الصفات ونعوتَهم أفضلُ النعوتِ، فوصَفَهم بأنَّهم {يَمۡشونَ على الأرضِ هَوۡناً}؛ أي: ساكنين متواضعين لله وللخَلْق؛ فهذا وصفٌ لهم بالوقارِ والسَّكينةِ والتَّواضُع لله ولعبادِهِ، {وإذا خاطَبَهُمُ الجاهلونَ}؛ أي: خطابَ جهل؛ بدليل إضافةِ الفعل وإسناده لهذا الوصفِ، {قالوا سلاماً}؛ أي: خاطَبوهم خطاباً يَسْلمونَ فيه من الإثم، ويَسْلَمونَ من مقابلة الجاهل بجهلِهِ"]]},{"id":"birr","t":"بر الوالدين","d":"قرن الله الإحسان إلى الوالدين بعبادته، وجعل برّهما من أعظم القربات، وأوجب الأدب معهما والدعاء لهما حتى مع الاختلاف.","r":[[17,23,24],[31,14,15],[46,15,15],[4,36,36],[19,14,14],[19,32,32],[29,8,8],[2,83,83]],"q":[["qurtubi",17,23,"استنباط","الخامسة- روى الترمذي عن عُمَرَ قَالَ: كَانَتْ تَحْتِي امْرَأَةٌ أُحِبُّهَا، وَكَانَ أَبِي يَكْرَهُهَا فَأَمَرَنِي أَنْ أُطَلِّقَهَا فَأَبَيْتُ، فَذَكَرَتْ ذَلِكَ لِلنَّبِيِّ ﷺ فَقَالَ: \"يَا عَبْدَ اللَّهِ بْنَ عُمَرَ طَلِّقِ امْرَأَتَكَ\". قَالَ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. السَّادِسَةُ- رَوَى الصَّحِيحُ عَنْ أَبِي هُرَيْرَةَ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ ﷺ فَقَالَ: مَنْ أَحَقُّ النَّاسَ بِحُسْنِ صَحَابَتِي؟ قَالَ: \"أُمُّكَ\" قَالَ: ثُمَّ مَنْ؟ قَالَ: \"ثُمَّ أُمُّكَ\" قَالَ: ثُمَّ مَنْ؟ قَالَ: \"ثُمَّ أُمُّكَ\" قَالَ: ثُمَّ مَنْ؟ قَالَ: \"ثُمَّ أَبُوكَ\". فَهَذَا الْحَدِيثُ يَدُلُّ عَلَى أَنَّ مَحَبَّةَ الْأُمِّ وَالشَّفَقَةَ عَلَيْهَا يَنْبَغِي أَنْ تَكُونَ ثَلَاثَةَ أَمْثَالِ مَحَبَّةِ الْأَبِ، لِذِكْرِ النَّبِيِّ ﷺ الْأُمَّ ثَلَاثَ مَرَّاتٍ وَذِكْرِ الْأَبِ فِي الرَّابِعَةِ فَقَطْ."],["tabari",4,36,"ترجيح","قال أبو جعفر: وأولى القولين في ذلك بالصواب، قول من قال:\"معنى، الجنب، في هذا الموضع: الغريبُ البعيد، مسلمًا كان أو مشركًا، يهوديًا كان أو نصرانيًا\"، لما بينا قبل من أن\"الجار ذي القربى\"، هو الجار ذو القرابة والرحم. والواجب أن يكون\"الجار ذو الجنابة\"، الجار البعيد، ليكون ذلك وصية بجميع أصناف الجيران قريبهم وبعيدهم."],["qurtubi",4,36,"نظر واستنباط","قُلْتُ: وَعَلَى هَذَا فَالْوَصَاةُ بِالْجَارِ مَأْمُورٌ بِهَا مَنْدُوبٌ إِلَيْهَا مُسْلِمًا كَانَ أَوْ كَافِرًا، وَهُوَ الصَّحِيحُ. وَالْإِحْسَانُ قَدْ يَكُونُ بِمَعْنَى الْمُوَاسَاةِ، وَقَدْ يَكُونُ بِمَعْنَى حُسْنِ الْعِشْرَةِ وَكَفِّ الْأَذَى وَالْمُحَامَاةِ دُونَهُ. رَوَى الْبُخَارِيُّ عَنْ عَائِشَةُ عَنِ النَّبِيِّ ﷺ قَالَ: (مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ). وَرُوِيَ عَنْ أَبِي شُرَيْحٍ أَنَّ النَّبِيَّ ﷺ قَالَ: (وَاللَّهِ لَا يُؤْمِنُ وَاللَّهِ لَا يُؤْمِنُ وَاللَّهِ لَا يُؤْمِنُ) قِيلَ: يَا رَسُولَ اللَّهِ وَمَنْ؟ قَالَ: (الَّذِي لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ) وَهَذَا عَامٌّ فِي كُلِّ جار. وقد أكد عليه السلام ترك إذ ايته بِقَسَمِهِ ثَلَاثَ مَرَّاتٍ، وَأَنَّهُ لَا يُؤْمِنُ الْإِيمَانَ الْكَامِلَ مَنْ آذَى جَارَهُ."]],"l":[["saadi",2,83,"لطيفة واستنباط","فقوله:{وإذ أخذنا ميثاق بني إسرائيل}؛ هذا من قسوتهم أن كل أمر أمروا به استعصوا، فلا يقبلونه إلا بالأيمان الغليظة والعهود الموَثَّقة {لا تعبدون إلا الله}؛ هذا أمر بعبادة الله وحده ونهي عن الشرك به، وهذا أصل الدين فلا تقبل الأعمال كلها إن لم يكن هذا أساسها، فهذا حق الله تعالى على عباده، ثم قال:{وبالوالدين إحساناً}؛ أي أحسنوا بالوالدين إحساناً، وهذا يعم كل إحسان قولي وفعلي مما هو إحسان إليهم، وفيه النهي عن الإساءة إلى الوالدين أو عدم الإحسان والإساءة؛ لأن الواجب الإحسان، والأمر بالشيء نهي عن ضده، وللإحسان ضدان: الإساءة وهي أعظم جرماً، وترك الإحسان بدون إساءة وهذا محرم لكن لا يجب أن يلحق بالأول."]]}]},{"id":"qasas","t":"القصص","ic":"i-scroll","d":"قصص الأنبياء والصالحين: مواضعها في القرآن، وما فيها من عبر وهدايات، بنقول المفسرين.","tp":[{"id":"adam","t":"قصة آدم عليه السلام","d":"قصة خلق آدم عليه السلام وتكريمه، وسجود الملائكة له، وامتناع إبليس، والنزول إلى الأرض، وفيها أصل العداوة والتوبة.","r":[[2,30,39],[7,11,25]],"q":[["qurtubi",2,31,"استنباط","الرَّابِعَةُ- وَاخْتَلَفَ الْمُتَأَوِّلُونَ أَيْضًا هَلْ عَرَضَ عَلَى الْمَلَائِكَةِ أَسْمَاءَ الْأَشْخَاصِ أَوِ الْأَسْمَاءَ دُونَ الْأَشْخَاصِ، فَقَالَ ابْنُ مَسْعُودٍ وَغَيْرُهُ: عَرَضَ الْأَشْخَاصَ لِقَوْلِهِ تَعَالَى: \"عَرَضَهُمْ\" وَقَوْلِهِ: \"أَنْبِئُونِي بِأَسْماءِ هؤُلاءِ\". وَتَقُولُ الْعَرَبُ: عَرَضْتُ الشَّيْءَ فَأَعْرَضَ، أَيْ أَظْهَرْتُهُ فَظَهَرَ. وَمِنْهُ: عَرَضْتُ الشَّيْءَ لِلْبَيْعِ. وَفِي الْحَدِيثِ (إِنَّهُ عَرَضَهُمْ أَمْثَالَ الذَّرِّ). وَقَالَ ابْنُ عَبَّاسٍ وَغَيْرُهُ: عَرَضَ الْأَسْمَاءَ. وَفِي حَرْفِ ابْنِ مَسْعُودٍ: \"عَرَضَهُنَّ\"، فَأَعَادَ عَلَى الْأَسْمَاءِ دُونَ الْأَشْخَاصِ، لِأَنَّ الْهَاءَ وَالنُّونَ أَخَصُّ بِالْمُؤَنَّثِ. وَفِي حَرْفِ أُبَيٍّ: \"عَرَضَهَا\". مُجَاهِدٌ: أَصْحَابُ الْأَسْمَاءِ."],["tabari",7,11,"ترجيح","وإنما قلنا هذا القول أولى الأقوال في ذلك بالصواب، لأن الذي يتلو ذلك قوله: ﴿ثم قلنا للملائكة اسجدوا لآدم﴾ ، ومعلوم أن الله تبارك وتعالى قد أمر الملائكة بالسجود لآدم، قبل أن يصوِّر ذريته في بطون أمهاتهم، بل قبل أن يخلُق أمهاتهم."],["qurtubi",2,32,"استنباط","الثانية: قَوْلُهُ تَعَالَى: ﴿سُبْحانَكَ﴾ \"سُبْحَانَ\" مَنْصُوبٌ عَلَى الْمَصْدَرِ عِنْدَ الْخَلِيلِ وَسِيبَوَيْهِ، يُؤَدِّي عَنْ مَعْنَى نُسَبِّحُكَ تَسْبِيحًا. وَقَالَ الْكِسَائِيُّ: هُوَ مَنْصُوبٌ عَلَى أَنَّهُ نداء مضاف. و (الْعَلِيمُ) فعيل للمبالغة والتكثير في المعلومات في خلق الله تعالى. و \"الْحَكِيمُ\" مَعْنَاهُ الْحَاكِمُ، وَبَيْنَهُمَا مَزِيدُ الْمُبَالَغَةِ. وَقِيلَ معناه المحكم يجئ والحكيم عَلَى هَذَا مِنْ صِفَاتِ الْفِعْلِ، صُرِفَ عَنْ مُفْعِلٍ إِلَى فَعِيلٍ، كَمَا صُرِفَ عَنْ مُسْمِعٍ إِلَى سَمِيعٍ وَمُؤْلِمٍ إِلَى أَلِيمٍ، قَالَهُ ابْنُ الْأَنْبَارِيِّ. وَقَالَ قَوْمٌ: (الْحَكِيمُ) الْمَانِعُ مِنَ الْفَسَادِ، وَمِنْهُ سُمِّيَتْ حِكْمَةُ اللِّجَامِ، لِأَنَّهَا تَمْنَعُ الْفَرَسَ مِنَ الْجَرْيِ وَالذَّهَابِ فِي غَيْرِ قَصْدٍ. قَالَ جَرِيرٌ:"]],"l":[["saadi",2,30,"لطيفة واستنباط","وفيه أن العبد إذا خفيت عليه حكمة الله في بعض المخلوقات، والمأمورات؛ فالواجب عليه التسليم واتهامُ عقله والإقرار لله بالحكمة؛ وفيه اعتناء الله بشأن الملائكة وإحسانه بهم بتعليمهم ما جهلوا، وتنبيههم على ما لم يعلموه."],["saadi",2,30,"لطيفة واستنباط","ثم لما كان قول الملائكة عليهم السلام فيه إشارة إلى فضلهم على الخليفة الذي يجعله الله في الأرض، أراد الله تعالى أن يبين لهم من فضل آدم ما يعرفون به فضله، وكمال حكمة الله وعلمه."],["saadi",2,30,"لطيفة واستنباط","وفي هذه الآيات من العِبَر والآيات إثبات الكلام لله تعالى، وأنه لم يزل متكلماً يقول ما شاء، ويتكلم بما شاء وأنه عليم حكيم، وفيه أن العبد إذا خفيت عليه حكمة الله في بعض المخلوقات، والمأمورات؛ فالواجب عليه التسليم واتهامُ عقله والإقرار لله بالحكمة؛ وفيه اعتناء الله بشأن الملائكة وإحسانه بهم بتعليمهم ما جهلوا، وتنبيههم على ما لم يعلموه."]]},{"id":"nuh","t":"قصة نوح عليه السلام","d":"دعوة نوح عليه السلام قومه ألف سنة إلا خمسين عاماً، وصبره عليهم، وبناء السفينة والطوفان، ونجاة المؤمنين.","r":[[11,25,48],[71,1,10]],"q":[["tabari",11,39,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك أن يقال كما قال الله: ﴿وما آمن معه إلا قليل﴾ ، يصفهم بأنهم كانوا قليلا ولم يحُدّ عددهم بمقدار، ولا خبر عن رسول الله ﷺ صحيح، فلا ينبغي أن يُتَجاوز في ذلك حدُّ الله، إذ لم يكن لمبلغ عدد ذلك حدٌّ من كتاب الله، أو أثر عن رسول الله ﷺ."],["qurtubi",11,27,"استنباط","الثَّانِيَةُ- قَوْلُهُ تَعَالَى: ﴿وَما نَراكَ اتَّبَعَكَ إِلَّا الَّذِينَ هُمْ أَراذِلُنا﴾ أَرَاذِلُ جَمْعُ أَرْذُلٍ وَأَرْذُلٌ جَمْعُ رَذْلٍ، مِثْلُ كَلْبٍ وَأَكْلُبٍ وَأَكَالِبَ. وَقِيلَ: وَالْأَرَاذِلُ جَمْعُ الْأَرْذَلِ، كَأَسَاوِدَ جَمْعُ الْأَسْوَدِ مِنَ الْحَيَّاتِ. وَالرَّذْلُ النَّذْلُ، أَرَادُوا اتَّبَعَكَ أَخِسَّاؤُنَا وَسَقَطُنَا وَسَفِلَتُنَا. قَالَ الزَّجَّاجُ: نَسَبُوهُمْ إِلَى الْحِيَاكَةِ، وَلَمْ يَعْلَمُوا أَنَّ الصِّنَاعَاتِ لَا أَثَرَ لَهَا فِي الدِّيَانَةِ. قَالَ النَّحَّاسُ: الأراذل هم الفقراء، والذين لأحسب لَهُمْ، وَالْخَسِيسُو الصِّنَاعَاتِ. وَفِي الْحَدِيثِ \"أَنَّهُمْ كَانُوا حَاكَةً وَحَجَّامِينَ\"."]],"l":[["saadi",71,1,"لطيفة واستنباط","ففيه تنبيهٌ على عظم خلق هذه الأشياء، وكثرة المنافع في الشمس والقمر، الدالَّة على رحمة الله وسعة إحسانه؛ فالعظيم الرحيم يستحقُّ أن يعظَّم ويُحبَّ ويُخاف ويُرجى."]]},{"id":"ibrahim","t":"قصة إبراهيم عليه السلام","d":"خليل الرحمن عليه السلام: محاجّته قومه ومن آتاه الله الملك، وتحطيم الأصنام ونجاته من النار، وبناء البيت، وابتلاء الذبح.","r":[[2,258,260],[21,51,70],[37,99,111],[6,74,79],[14,35,41],[2,124,127]],"q":[["qurtubi",37,102,"استنباط","الْخَامِسَةُ- قَوْلُهُ تَعَالَى: ﴿فَلَمَّا أَسْلَما﴾ أَيِ انْقَادَا لِأَمْرِ اللَّهِ. وَقَرَأَ ابْنُ مَسْعُودٍ وَابْنُ عَبَّاسٍ وَعَلِيٌّ رِضْوَانُ اللَّهِ عَلَيْهِمْ \"فَلَمَّا سَلَّمَا\" أَيْ فَوَّضَا أَمْرَهُمَا إِلَى اللَّهِ. وَقَالَ ابْنُ عَبَّاسٍ: اسْتَسْلَمَا. وَقَالَ قَتَادَةُ: أَسْلَمَ أَحَدُهُمَا نَفْسَهُ لِلَّهِ عَزَّ وَجَلَّ وَأَسْلَمَ الْآخَرُ ابْنَهُ. \"وَتَلَّهُ لِلْجَبِينِ\" قَالَ قَتَادَةُ: كَبَّهُ وَحَوَّلَ وَجْهَهُ إِلَى الْقِبْلَةِ. وَجَوَابُ \"لَمَّا\" مَحْذُوفٌ عِنْدَ الْبَصْرِيِّينَ تَقْدِيرَهُ \"فَلَمَّا أَسْلَما وَتَلَّهُ لِلْجَبِينِ\" فَدَيْنَاهُ بِكَبْشٍ. وَقَالَ الْكُوفِيُّونَ: الْجَوَابُ \"نَادَيْنَاهُ\" وَالْوَاوُ زَائِدَةٌ مُقْحَمَةٌ، كَقَوْلِهِ: ﴿فَلَمَّا ذَهَبُوا بِهِ وَأَجْمَعُوا أَنْ يَجْعَلُوهُ فِي غَيابَتِ الْجُبِّ وَأَوْحَيْنا﴾ [يوسف: ١٥] أَيْ أَوْحَيْنَا."],["tabari",2,259,"ترجيح","قال أبو جعفر: وأولى الأقوال في هذه الآية بالصواب قولُ من قال: إن الله تعالى ذكره بعث قائل: ﴿أنَّى يحيي هذه الله بعد موتها﴾ من مماته، ثم أراه نظير ما استنكر من إحياء الله القرية التي مرّ بها بعد مماتها عيانًا من نفسه وطعامه وحماره. فحمل تعالى ذكره ما أراه من إحيائه نفسه وحماره مثلا لما استنكر من إحيائه أهل القرية التي مرّ بها خاويةً على عروشها، وجعل ما أراه من العِبرة في طعامه وشرابه، عبرة له وحجة عليه في كيفية إحيائه منازل القرية وجِنانها. وذلك هو معنى قول مجاهد الذي ذكرناه قبل."],["qurtubi",37,102,"استنباط","السَّابِعَةُ- قَوْلُهُ تَعَالَى: ﴿وَفَدَيْناهُ بِذِبْحٍ عَظِيمٍ﴾ الذِّبْحُ اسْمُ الْمَذْبُوحِ وَجَمْعُهُ ذُبُوحٌ، كَالطِّحْنِ اسْمُ الْمَطْحُونِ. وَالذَّبْحُ بِالْفَتْحِ الْمَصْدَرُ. \"عَظِيمٍ\" أَيْ عَظِيمُ الْقَدْرِ وَلَمْ يُرِدْ عَظِيمَ الْجُثَّةِ. وَإِنَّمَا عَظُمَ قَدْرُهُ لِأَنَّهُ فُدِيَ بِهِ الذَّبِيحُ، أَوْ لِأَنَّهُ مُتَقَبَّلٌ. قَالَ النَّحَّاسُ: عَظِيمٌ فِي اللُّغَةِ يَكُونُ لِلْكَبِيرِ وَلِلشَّرِيفِ. وَأَهْلُ التَّفْسِيرِ عَلَى أَنَّهُ هَاهُنَا لِلشَّرِيفِ، أَوِ الْمُتَقَبَّلِ. وَقَالَ ابْنُ عَبَّاسٍ: هُوَ الْكَبْشُ الَّذِي تَقَرَّبَ بِهِ هَابِيلُ، وَكَانَ فِي الْجَنَّةِ يَرْعَى حَتَّى فَدَى اللَّهُ بِهِ إِسْمَاعِيلَ. وَعَنْهُ أَيْضًا: أَنَّهُ كَبْشٌ أَرْسَلَهُ اللَّهُ مِنَ الْجَنَّةِ كَانَ قَدْ رَعَى فِي الْجَنَّةِ أَرْبَعِينَ خَرِيفًا."]],"l":[["saadi",21,51,"لطيفة واستنباط","ومن بركةِ الشام أنَّ كثيراً من الأنبياء كانوا فيها، وأنَّ الله اختارَها مهاجَرَاً لخليلِهِ، وفيها أحدُ بيوتِهِ الثلاثة المقدَّسة، وهو بيت المقدس."]]},{"id":"yusuf","t":"قصة يوسف عليه السلام","d":"قصة يوسف عليه السلام «أحسن القصص»: رؤياه وكيد إخوته، وفتنة امرأة العزيز وصبره وعفته، ثم التمكين والعفو.","r":[[12,4,6],[12,23,34],[12,53,53],[12,90,101]],"q":[["tabari",12,24,"ترجيح","قال أبو جعفر: وأولى الأقوال في ذلك بالصواب أن يقال: إن الله جل ثناؤه أخبر عن همِّ يوسف وامرأة العزيز كل واحد منهما بصاحبه، لولا أن رأى يوسف برهان ربه، وذلك آيةٌ من الله، زجرته عن ركوب ما همَّ به يوسف من الفاحشة = وجائز أن تكون تلك الآية صورة يعقوب = وجائز أن تكون صورة الملك - وجائز أن يكون الوعيد في الآيات التي ذكرها الله في القرآن على الزنا = ولا حجة للعذر قاطعة بأيِّ ذلك [كان] من أيٍّ. والصواب أن يقال في ذلك ما قاله الله تبارك وتعالى، والإيمان به، وترك ما عدا ذلك إلى عالمه."],["tabari",12,26,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك، قول من قال: كان صبيًّا في المهد = للخبر الذي ذكرناه عن رسول الله ﷺ. أنه ذكر من تكلم في المهد. فذكر أنَّ أحدهم صاحب يوسف."],["tabari",12,31,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك أن يقال: إن الله أخبر عنهن أنهن قطَّعن أيديهن وهن لا يشعرن لإعظام يوسف، وجائز أن يكون ذلك قطعًا بإبانة = وجائز أن يكون كان قطع حزّ وخدش = ولا قول في ذلك أصوب من التسليم لظاهر التنزيل."]],"l":[["saadi",12,23,"لطيفة واستنباط","وقد دعتْه إلى نفسها، فقالتْ:{هَيۡتَ لك}؛ أي: افعل الأمر المكروه وأقبلْ إليَّ! ومع هذا؛ فهو غريبٌ لا يحتشم مثله ما يحتشمه إذا كان في وطنه وبين معارفه، وهو أسيرٌ تحت يدها، وهي سيدتُه، وفيها من الجمال ما يدعو إلى ما هنالك، وهو شابٌّ عَزَبٌ، وقد توعدته إن لم يفعل ما تأمره به بالسجن أو العذاب الأليم، فصبر عن معصية الله مع وجود الداعي القويِّ فيه؛ لأنَّه قد همَّ فيها همًّا تَرَكَهُ لله، وقدَّم مراد الله على مراد النفس الأمَّارة بالسوء، ورأى من برهان ربِّه ـ وهو ما معه من العلم والإيمان الموجب لِتَرْكِ كلِّ ما حرَّم الله ـ ما أوجب له البعد والانكفاف عن هذه المعصية الكبيرة، و {قال معاذَ الله}"]]},{"id":"musa","t":"قصة موسى عليه السلام","d":"قصة موسى عليه السلام: مولده ونشأته في بيت فرعون، وخروجه إلى مدين، وكلام الله له وبعثته إلى فرعون.","r":[[20,9,24],[28,7,13],[28,29,35]],"q":[["tabari",20,11,"ترجيح","قال أبو جعفر: وأولى القولين في ذلك بالصواب قول من قال: أمره الله تعالى ذكره بخلع نعليه ليباشر بقدميه بركة الوادي، إذ كان واديا مقدسا."],["qurtubi",20,24,"نظر واستنباط","قُلْتُ: وَهَذَا فِيهِ نَظَرٌ، لِأَنَّهُ لَوْ كَانَ ذَلِكَ لَمَا قَالَ فِرْعَوْنُ: \"وَلا يَكادُ يُبِينُ\" حِينَ كَلَّمَهُ مُوسَى بِلِسَانٍ ذَلِقٍ فَصِيحٍ. وَاللَّهُ أَعْلَمُ. وَقِيلَ: إِنَّ تِلْكَ الْعُقْدَةَ حَدَثَتْ بِلِسَانِهِ عِنْدَ مُنَاجَاةِ رَبِّهِ، حَتَّى لَا يُكَلِّمَ غَيْرَهُ إلا بإذنه."],["qurtubi",28,7,"نظر واستنباط","فَقُلْتُ: قَاتَلَكِ اللَّهُ مَا أفصحك! فقالت: أو يعد هَذَا فَصَاحَةً مَعَ قَوْلُهُ تَعَالَى: ﴿وَأَوْحَيْنا إِلى أُمِّ مُوسى أَنْ أَرْضِعِيهِ﴾ الْآيَةَ، فَجَمَعَ فِي آيَةٍ وَاحِدَةٍ بَيْنَ أَمْرَيْنِ وَنَهْيَيْنِ وَخَبَرَيْنِ وَبِشَارَتَيْنِ."]],"l":[["saadi",20,16,"لطيفة واستنباط","وفي هذا تنبيهٌ وإشارةٌ إلى التحذير عن كلِّ داع إلى باطل، يصدُّ عن الإيمان الواجب أو عن كمالِهِ، أو يوقع الشبهةَ في القلب، وعن النظر في الكتب المشتملة على ذلك."],["saadi",20,16,"لطيفة واستنباط","وإنَّما حذَّر الله تعالى عمَّن هذه حاله؛ لأنَّه من أخوف ما يكون على المؤمن بوسوسته وتدجيله وكون النفوس مجبولةً على التشبُّه والاقتداء بأبناء الجنس، وفي هذا تنبيهٌ وإشارةٌ إلى التحذير عن كلِّ داع إلى باطل، يصدُّ عن الإيمان الواجب أو عن كمالِهِ، أو يوقع الشبهةَ في القلب، وعن النظر في الكتب المشتملة على ذلك."],["saadi",20,24,"لطيفة واستنباط","وهذا السؤال من موسى عليه السلام، يدلُّ على كمال معرفته بالله وكمال فطنتِهِ ومعرفتِهِ للأمور وكمال نصحِهِ، وذلك أنَّ الدَّاعي إلى الله المرشِدِ للخلق، خصوصاً إذا كان المدعوُّ من أهل العناد والتكبُّر والطُّغيان ، يحتاج إلى سعة صدر، وحلم تامٍّ على ما يصيبه من الأذى، ولسان فصيح يتمكَّن من التعبير به عن ما يريده ويقصده، بل الفصاحةُ والبلاغة لصاحب هذا المقام من ألزم ما يكون؛ لكثرة المراجعات والمراوضات، ولحاجته لتحسين الحقِّ وتزيينه بما يقدر عليه؛ ليحبِّبه إلى النفوس، وإلى تقبيح الباطل وتهجينه لينفِّرَ عنه، ويحتاج مع ذلك أيضاً أن يتيسَّر له أمره، فيأتي البيوت من أبوابها"]]},{"id":"isa","t":"قصة مريم وعيسى عليهما السلام","d":"قصة مريم عليها السلام وكرامتها ومولد عيسى عليه السلام ومعجزاته، وبراءة القرآن من الغلو والجفاء فيهما.","r":[[3,45,51],[19,16,33]],"q":[["tabari",19,24,"ترجيح","قال أبو جعفر: وأولى القولين في ذلك عندنا قول من قال: الذي ناداها ابنها عيسى، وذلك أنه من كناية ذكره أقرب منه من ذكر جبرائيل، فردّه على الذي هو أقرب إليه أولى من ردّه على الذي هو أبعد منه. ألا ترى في سياق قوله ﴿فَحَمَلَتْهُ فَانْتَبَذَتْ بِهِ مَكَانًا قَصِيًّا﴾ يعني به: فحملت عيسى فانتبذت به، ثم قيل: فناداها نسقا على ذلك من ذكر عيسى والخبر عنه. ولعلة أخرى، وهي قوله ﴿فَأَشَارَتْ إِلَيْهِ﴾ ولم تشر إليه إن شاء الله ألا وقد علمت أنه ناطق في حاله تلك، وللذي كانت قد عرفت ووثقت به منه بمخاطبته إياها بقوله لها ﴿أَنْ لا تَحْزَنِي قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا﴾ وما أخبر الله عنه أنه قال لها أشيري للقوم إليه، ولو كان ذلك قولا من جبرائيل، لكان خليقا أن يكون في ظاهر الخبر، مبينا أن عيسى سينطق، ويحتجّ عنها للقوم، وأمر منه لها بأن تشير إليه للقوم إذا سألوها عن حالها وحاله."],["tabari",19,24,"ترجيح","قال أبو جعفر: وأولى القولين في ذلك عندي بالصواب قيل من قال: عنى به الجدول، وذلك أنه أعلمها ما قد أتاها الله من الماء الذي جعله عندها، وقال لها ﴿وَهُزِّي إِلَيْكِ بِجِذْعِ النَّخْلَةِ تُسَاقِطْ عَلَيْكِ رُطَبًا جَنِيًّا فَكُلِي﴾ من هذا الرطب ﴿وَاشْرَبي﴾ من هذا الماء ﴿وَقَرِّي عَيْنًا﴾ بولدك، والسريّ معروف من كلام العرب أنه النهر الصغير؛ ومنه قول لبيد:"],["tabari",19,24,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك عندي أن يقال: إن هذه القراءات الثلاث، أعني ﴿تَسَّاقَطُ﴾ بالتاء وتشديد السين، وبالتاء وتخفيف السين، وبالياء وتشديد السين، قراءات متقاربات المعاني، قد قرأ بكل واحدة منهن قرّاء أهل معرفة بالقرآن، فبأيّ ذلك قرأ القارئ فمصيب الصواب فيه، وذلك أن الجذع إذا تساقط رطبًا، وهو ثابت غير مقطوع، فقد تساقطت النخلة رطبًا، وإذا تساقطت النخلة رطبًا، فقد تساقطت النخلة بأجمعها، جذعها وغير جذعها، وذلك أن النخلة ما دامت قائمة على أصلها، فإنما هي جذع وجريد وسعف، فإذا قطعت صارت جذعا، فالجذع الذي أمرت مريم بهزّه لم يذكر أحد نعلمه أنه كان جذعًا مقطوعًا غير السديّ، وقد زعم أنه عاد بهزِّها إياه نخلة، فقد صار معناه ومعنى من قال: كان المتساقط. عليها رطبا نخلة واحدا، فتبين بذلك صحة ما قلنا."]],"l":[["saadi",3,45,"لطيفة واستنباط","وفيه إشارة إلى كثرة صلاتها وملازمتها لمحرابها {وجد عندها رزقاً}؛ هنيئاً معدًّا قال:{أنى لك هذا قالت هو من عند الله إن الله يرزقُ من يشاء بغير حساب}؛ فلما رأى زكريا هذه الحال والبر واللطف من الله بها، ذكَّرَه أن يسأل الله تعالى حصول الولد على حين اليأس منه فقال:{رب هَب لي من لَدُنك ذرية طيبة إنك سميعُ الدُّعاء."],["saadi",3,45,"لطيفة واستنباط","ثم إن الله تعالى أكرم مريم وزكريا حيث يسَّر لمريم من الرزق الحاصل بلا كدٍّ ولا تعب، وإنما هو كرامة أكرمها الله به، إذ {كلما دخل عليها زكريا المحراب}؛ وهو محل العبادة وفيه إشارة إلى كثرة صلاتها وملازمتها لمحرابها {وجد عندها رزقاً}؛ هنيئاً معدًّا قال:{أنى لك هذا قالت هو من عند الله إن الله يرزقُ من يشاء بغير حساب}؛ فلما رأى زكريا هذه الحال والبر واللطف من الله بها، ذكَّرَه أن يسأل الله تعالى حصول الولد على حين اليأس منه فقال:{رب هَب لي من لَدُنك ذرية طيبة إنك سميعُ الدُّعاء."]]},{"id":"kahf","t":"قصة أصحاب الكهف","d":"فتية آمنوا بربهم ففرّوا بدينهم إلى الكهف، فحفظهم الله ونامت أعينهم سنين؛ وفيها درس في الثبات على الإيمان.","r":[[18,9,26]],"q":[["tabari",18,19,"ترجيح","وأولى الأقوال في ذلك بالصواب عندي قول من قال: إن الله تعالى بعثهم من رقدتهم ليتساءلوا بينهم كما بيَّنا قبل، لأن الله عزّ ذكره، كذلك أخبر عباده في كتابه، وإن الله أعثر عليهم القوم الذين أعثرهم عليهم، ليتحقق عندهم ببعث الله هؤلاء الفتية من رقدتهم بعد طول مدتها بهيئتهم يوم رقدوا، ولم يشيبوا على مرّ الأيام والليالي عليهم، ولم يهرموا على كرّ الدهور والأزمان فيهم قدرته على بعث من أماته في الدنيا من قبره إلى موقف القيامة يوم القيامة، لأن الله عزّ ذكره بذلك أخبرنا، فقال: ﴿وَكَذَلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوا أَنَّ وَعْدَ اللَّهِ حَقٌّ وَأَنَّ السَّاعَةَ لا رَيْبَ فِيهَا﴾ ."],["qurtubi",18,19,"استنباط","الثَّالِثَةُ- فِي هَذِهِ الْبَعْثَةِ بِالْوَرِقِ دَلِيلٌ عَلَى الْوِكَالَةِ وَصِحَّتِهَا. وَقَدْ وَكَّلَ عَلِيُّ بْنُ أَبِي طَالِبٍ أَخَاهُ عَقِيلًا عِنْدَ عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ، وَلَا خِلَافَ فِيهَا فِي الْجُمْلَةِ. وَالْوَكَالَةُ مَعْرُوفَةٌ فِي الْجَاهِلِيَّةِ وَالْإِسْلَامِ، أَلَا تَرَى إِلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ كَيْفَ وَكَّلَ أُمَيَّةَ بْنَ خَلَفٍ بِأَهْلِهِ وَحَاشِيَتِهِ بِمَكَّةَ، أَيْ يَحْفَظُهُمْ، وَأُمَيَّةُ مُشْرِكٌ، وَالْتَزَمَ عَبْدُ الرَّحْمَنِ لِأُمَيَّةَ مِنْ حِفْظِ حَاشِيَتِهِ بِالْمَدِينَةِ مِثْلَ ذَلِكَ مُجَازَاةً لِصُنْعِهِ."],["tabari",18,19,"ترجيح","وأولى الأقوال عندي في ذلك بالصواب: قول من قال: معنى ذلك: أحلّ وأطهر، وذلك أنه لا معنى في اختيار الأكثر طعاما للشراء منه إلا بمعنى إذا كان أكثرهم طعاما، كان خليقا أن يكون الأفضل منه عنده أوجد، وإذا شرط على المأمور الشراء من صاحب الأفضل، فقد أمر بشراء الجيد، كان ما عند المشتري ذلك منه قليلا الجيد أو كثيرا، وإنما وجه من وجه تأويل أزكى إلى الأكثر، لأنه وجد العرب تقول: قد زكا مال فلان: إذا كثر، وكما قال الشاعر:"]],"l":[["saadi",18,13,"لطيفة واستنباط","ولهذا قالوا:{لن نَدۡعُوَ من دونِهِ إلهاً}؛ أي: من سائر المخلوقات، {لقد قُلۡنا إذاً} ـ أي: إن دَعَوْنا معه آلهةً بعدما علمنا أنَّه الربُّ الإله الذي لا تجوز ولا تنبغي العبادة إلاَّ له ـ {شططاً}؛ أي: ميلاً عظيماً عن الحقِّ، وطريقاً بعيدة عن الصواب، فجمعوا بين الإقرار بتوحيد الربوبيَّة وتوحيد الإلهيَّة والتزام ذلك وبيان أنَّه الحقُّ وما سواه باطلٌ، وهذا دليلٌ على كمال معرفتهم بربِّهم وزيادة الهدى من الله لهم."],["saadi",18,17,"لطيفة واستنباط","هذا حفظُهم من الأرض، وأما حفظُهم من الآدميين؛ فأخبر أنَّه حماهم بالرُّعب الذي نَشَرَهُ الله عليه؛ فلو اطَّلع عليهم أحدٌ؛ لامتلأ قلبه رعباً وولَّى منهم فراراً، وهذا الذي أوجب أن يبقَوْا كلَّ هذه المدَّة الطويلة وهم لم يعثر عليهم أحدٌ مع قربهم من المدينة جدًّا، والدليل على قربهم أنَّهم لما استيقظوا؛ أرسلوا أحدَهم يشتري لهم طعاماً من المدينة، وبقوا في انتظاره، فدلَّ ذلك على شدَّة قربهم منها."],["saadi",18,21,"لطيفة واستنباط","وفي هذه القصة دليلٌ على أنَّ من فرَّ بدينه من الفتن؛ سلَّمه الله منها، وأنَّ مَن حرص على العافية؛ عافاه الله، ومن أوى إلى الله؛ آواه الله وجعله هدايةً لغيره، ومن تحمل الذُّلَّ في سبيله وابتغاء مرضاته؛ كان آخرُ أمره وعاقتبه العز العظيم من حيث لا يحتسب، وما عند الله خيرٌ للأبرار."]]},{"id":"dhulqarnayn","t":"قصة ذي القرنين","d":"ملك صالح مكّن الله له في الأرض فسار شرقاً وغرباً ينصر المظلوم ويبني السد على يأجوج ومأجوج متواضعاً لله.","r":[[18,83,98],[18,99,99]],"q":[],"l":[["saadi",18,83,"لطيفة واستنباط","وهذا يدلُّ على كونه من الملوك الصالحين [و] الأولياء العادلين العالمين؛ حيث وافق مرضاةَ الله في معاملة كلِّ أحدٍ بما يليق بحاله."]]}]},{"id":"ahkam","t":"الأحكام","ic":"i-book","d":"آيات الأحكام العملية مبوّبة: العبادات والمعاملات والأسرة والحدود، بنقول فقهية من أمهات التفسير.","tp":[{"id":"salat","t":"الصلاة","d":"الصلاة عماد الدين وأعظم الأركان بعد الشهادتين؛ فرضها الله في أوقات معلومة، وأمر بالمحافظة عليها وبصلاة الجمعة.","r":[[2,43,43],[2,238,239],[4,103,103],[17,78,79],[62,9,10]],"q":[["tabari",17,78,"ترجيح","وأولى القولين في ذلك بالصواب قول من قال: عنى بقوله ﴿أَقِمِ الصَّلاةَ لِدُلُوكِ الشَّمْسِ﴾ : صلاة الظهر، وذلك أن الدلوك في كلام العرب: الميل، يقال منه: دلك فلان إلى كذا: إذا مال إليه. ومنه الخبر الذي رُوي عن الحسن أن رجلا قال له: أيُدالك الرجل امرأته؟ يعني بذلك: أيميل بها إلى المماطلة بحقها. ومنه قول الراجز:"],["qurtubi",2,43,"استنباط","الْعَاشِرَةُ- وَيُكْرَهُ السُّجُودُ عَلَى كَوْرِ الْعِمَامَةِ، وَإِنْ كَانَ طَاقَةً أَوْ طَاقَتَيْنِ مِثْلَ الثِّيَابِ الَّتِي تَسْتُرُ الرُّكَبَ وَالْقَدَمَيْنِ فَلَا بَأْسَ، وَالْأَفْضَلُ مُبَاشَرَةُ الْأَرْضِ أَوْ مَا يُسْجَدُ عَلَيْهِ. فَإِنْ كَانَ هُنَاكَ مَا يُؤْذِيهِ أَزَالَهُ قَبْلَ دُخُولِهِ فِي الصَّلَاةِ، فَإِنْ لَمْ يَفْعَلْ فَلْيَمْسَحْهُ مَسْحَةً وَاحِدَةً. وَرَوَى مُسْلِمٌ عَنْ مُعَيْقِيبَ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ فِي الرَّجُلِ يُسَوِّي التُّرَابَ حَيْثُ يَسْجُدُ قَالَ (إِنْ كُنْتَ فَاعِلًا فَوَاحِدَةٌ) وَرُوِيَ عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كُنَّا نُصَلِّي مَعَ رَسُولِ اللَّهِ ﷺ فِي شِدَّةِ الْحَرِّ فَإِذَا لَمْ يَسْتَطِعْ أَحَدُنَا أَنْ يُمَكِّنَ جَبْهَتَهُ مِنَ الْأَرْضِ بَسَطَ ثَوْبَهُ فَسَجَدَ عَلَيْهِ."],["tabari",17,78,"ترجيح","وأولى القولين في ذلك بالصواب، قول من قال: الصلاة التي أمر النبيّ ﷺ بإقامتها عند غسق الليل، هي صلاة المغرب دون غيرها، لأن غسق الليل هو ما وصفنا من إقبال الليل وظلامه، وذلك لا يكون إلا بعد مغيب الشمس. فأما صلاة العصر، فإنها مما تقام بين ابتداء دلوك الشمس إلى غسق الليل، لا عند غسق الليل، وأما قوله ﴿وَقُرْآنَ الْفَجْرِ﴾ فإن معناه وأقم قرآن الفجر: أي ما تقرأ به صلاة الفجر من القرآن، والقرآن معطوف على الصلاة في قوله ﴿أَقِمِ الصَّلاةَ لِدُلُوكِ الشَّمْسِ﴾ ."]],"l":[["saadi",2,43,"لطيفة واستنباط","وأيضاً فإن في قوله:{مصدقاً لما معكم}؛ إشارة إلى أنكم إن لم تؤمنوا به عاد ذلك عليكم بتكذيب ما معكم؛ لأن ما جاء به هو الذي جاء به موسى وعيسى وغيرهما من الأنبياء، فتكذيبكم له تكذيب لما معكم."],["saadi",2,238,"لطيفة واستنباط","وفي الآية الكريمة فضيلة العلم وأن على من علمه الله ما لم يكن يعلم الإكثارَ من ذكر الله، وفيه الإشعارُ أيضاً أن الإكثار من ذكره سبب لتعليم علوم أخر لأن الشكر مقرون بالمزيد."],["saadi",17,78,"لطيفة واستنباط","وفيها أنَّ الوقت شرطٌ لصحَّة الصلاة، وأنَّه سببٌ لوجوبها؛ لأنَّ الله أمر بإقامتها لهذه الأوقات، وأنَّ الظهر والعصر يُجمعان، والمغرب والعشاء كذلك؛ للعذر؛ لأنَّ الله جمع وقتهما جميعاً."]]},{"id":"siyam","t":"الصيام","d":"فُرض صيام رمضان على هذه الأمة كما فُرض على من قبلها، مع الرخصة للمريض والمسافر، وبيان أحكام الإفطار والسحور والاعتكاف.","r":[[2,183,187]],"q":[["qurtubi",2,183,"نظر واستنباط","قُلْتُ: وَهُوَ مُقْتَضَى قَوْلِهِ تَعَالَى: \"فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ\" فَمَتَى أَتَى بِيَوْمٍ تَامٍّ بَدَلًا عَمَّا أَفْطَرَهُ فِي قَضَاءِ رَمَضَانَ فَقَدْ أَتَى بِالْوَاجِبِ عَلَيْهِ، وَلَا يَجِبُ عَلَيْهِ غَيْرُ ذَلِكَ، وَاللَّهُ أَعْلَمُ. الرَّابِعَةَ عَشْرَةَ- وَالْجُمْهُورُ عَلَى أَنَّ مَنْ أَفْطَرَ فِي رَمَضَانَ لِعِلَّةٍ فَمَاتَ مِنْ عِلَّتِهِ تِلْكَ، أَوْ سَافَرَ فَمَاتَ فِي سَفَرِهِ ذلك أنه لا شي عَلَيْهِ. وَقَالَ طَاوُسٌ وَقَتَادَةُ فِي الْمَرِيضِ يَمُوتُ قَبْلَ أَنْ يَصِحَّ: يُطْعَمُ عَنْهُ. الْخَامِسَةَ عَشْرَةَ- وَاخْتَلَفُوا فِيمَنْ مَاتَ وَعَلَيْهِ صَوْمٌ مِنْ رَمَضَانَ لَمْ يَقْضِهِ، فَقَالَ مَالِكٌ وَالشَّافِعِيُّ وَالثَّوْرِيُّ: لَا يَصُومُ أَحَدٌ عَنْ أَحَدٍ."],["tabari",2,184,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك عندنا أن الله تعالى ذكره عمم بقوله:\"فمن تطوع خيرًا\"، فلم يخصص بعض معاني الخير دون بعض. فإنّ جَمْع الصَوْم مع الفدية من تطوُّع الخير، وزيادةُ مسكين على جزاء الفدية من تطوُّع الخير. وجائز أن يكون تعالى ذكره عنى بقوله:\"فمن تطوع خيرًا\"، أيَّ هذه المعاني تطوّع به المفتدي من صومه، فهو خير له. لأن كل ذلك من تطوع الخير، ونوافل الفضل."],["qurtubi",2,183,"استنباط","الثَّالِثَةُ- اتَّفَقَ الْعُلَمَاءُ عَلَى أَنَّ الْمُسَافِرَ فِي رَمَضَانَ لَا يَجُوزُ لَهُ أَنْ يُبَيِّتَ الْفِطْرَ، لِأَنَّ الْمُسَافِرَ لَا يَكُونُ مُسَافِرًا بِالنِّيَّةِ بِخِلَافِ الْمُقِيمِ، وَإِنَّمَا يَكُونُ مُسَافِرًا بِالْعَمَلِ وَالنُّهُوضِ، وَالْمُقِيمُ لَا يَفْتَقِرُ إِلَى عَمَلٍ، لِأَنَّهُ إِذَا نَوَى الْإِقَامَةَ كَانَ مُقِيمًا فِي الْحِينِ، لِأَنَّ الْإِقَامَةَ لَا تَفْتَقِرُ إِلَى عَمَلٍ فَافْتَرَقَا."]],"l":[["saadi",2,183,"لطيفة واستنباط","وفي قوله:{فعدة من أيام}؛ فيه دليل على أنه يقضي عدد أيام رمضان كاملاً كان أو ناقصاً وعلى أنه يجوز أن يقضي أياماً قصيرة باردة عن أيام طويلة حارة كالعكس، وقوله:{وعلى الذين يطيقونه}؛ أي: يطيقون الصيام {فدية}؛ عن كل يوم يفطرونه {طعام مسكين}؛ وهذا في ابتداء فرض الصيام لما كانوا غير معتادين للصيام وكان فرضه حتماً فيه مشقة عليهم دَرَّجَهم الربُّ الحكيم بأسهل طريق، وخَيَّرَ المطيق للصوم بين أن يصوم وهو أفضل أو يطعم ولهذا قال:{وأن تصوموا خير لكم}؛ ثم بعد ذلك جعل الصيام حتماً على المطيق، وغير المطيق يفطر ويقضيه في أيام أُخَر، وقيل: وعلى الذين يطيقون؛ أي يتكلفونه، ويشق عليهم مشقة غير محتملة كالشيخ الكبير، فدية عن كل يوم مسكين، وهذا هو الصحيح."],["saadi",2,187,"لطيفة واستنباط","وفيه أنه إذا أكل ونحوه شاكًّا في طلوع الفجر فلا بأس عليه، وفيه دليل على استحباب السحور للأمر، وأنه يستحب تأخيره، أخذاً من معنى رخصة الله وتسهيله على العباد، وفيه أيضاً دليل على أنه يجوز أن يدركه الفجر وهو جنب من الجماع قبل أن يغتسل، ويصح صيامه لأن لازم إباحة الجماع إلى طلوع الفجر، أن يدركه الفجر وهو جنب، ولازم الحق حق {ثم}؛ إذا طلع الفجر {أتموا الصيام}؛ أي: الإمساك عن المفطرات {إلى الليل}؛ وهو غروب الشمس، ولما كان إباحة الوطء في ليالي الصيام ليست إباحة عامة لكل أحد، فإن المعتكف لا يحل له ذلك استثناه بقوله:{ولا تباشروهن وأنتم عاكفون في المساجد}؛ أي: وأنتم متصفون بذلك."],["saadi",2,187,"لطيفة واستنباط","ودلت الآية على مشروعية الاعتكاف وهو لزوم المسجد لطاعة الله تعالى وانقطاعاً إليه، وأن الاعتكاف لا يصح إلا في مسجدٍ، ويستفاد من تعريف المساجد أنها المساجد المعروفة عندهم، وهي التي تقام فيها الصلوات الخمس، وفيه أن الوطء من مفسدات الاعتكاف."]]},{"id":"zakat","t":"الزكاة والإنفاق","d":"الزكاة حق الله في المال، ومصارفها ثمانية بنص القرآن، ويُحثّ مع ذلك على الإنفاق الطيب في سبيل الله بإخلاص.","r":[[9,60,60],[9,103,103],[2,267,271]],"q":[["tabari",9,60,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك عندي: أن الله جعل الصدقة في معنيين أحدهما: سدُّ خَلَّة المسلمين، والآخر: معونة الإسلام وتقويته. فما كان في معونة الإسلام وتقوية أسبابه، فإنه يُعطاه الغني والفقير، لأنه لا يعطاه من يعطاه بالحاجة منه إليه، وإنما يعطاه معونةً للدين. وذلك كما يعطى الذي يُعطاه بالجهاد في سبيل الله، فإنه يعطى ذلك غنيًّا كان أو فقيرًا، للغزو، لا لسدّ خلته. وكذلك المؤلفة قلوبهم، يعطون ذلك وإن كانوا أغنياء، استصلاحًا بإعطائهموه أمرَ الإسلام وطلبَ تقويته وتأييده. وقد أعطى النبي ﷺ من أعطى من المؤلفة قلوبهم، بعد أن فتح الله عليه الفتوح، وفشا الإسلام وعز أهله. فلا حجة لمحتجّ بأن يقول: \"لا يتألف اليوم على الإسلام أحد، لامتناع أهله بكثرة العدد ممن أرادهم\"، وقد أعطى النبي ﷺ من أعطى منهم في الحال التي وصفت."],["qurtubi",9,60,"استنباط","الْخَامِسَةَ عَشْرَةَ- قَوْلُهُ تَعَالَى: ﴿وَفِي الرِّقابِ﴾ أَيْ فِي فَكِّ الرِّقَابِ، قَالَهُ ابْنُ عَبَّاسٍ وَابْنُ عُمَرَ، وَهُوَ مَذْهَبُ مَالِكٍ وَغَيْرِهِ. فَيَجُوزُ لِلْإِمَامِ أَنْ يَشْتَرِيَ رِقَابًا مِنْ مَالِ الصَّدَقَةِ يُعْتِقُهَا عَنِ الْمُسْلِمِينَ، وَيَكُونُ وَلَاؤُهُمْ لِجَمَاعَةِ الْمُسْلِمِينَ. وَإِنِ اشْتَرَاهُمْ صَاحِبُ الزَّكَاةِ وَأَعْتَقَهُمْ جَازَ. هَذَا تَحْصِيلُ مَذْهَبِ مَالِكٍ، وَرُوِيَ عَنِ ابْنِ عَبَّاسٍ وَالْحَسَنِ، وَبِهِ قَالَ أَحْمَدُ وَإِسْحَاقُ وَأَبُو عُبَيْدٍ. وَقَالَ أَبُو ثَوْرٍ: لَا يَبْتَاعُ مِنْهَا صَاحِبُ الزَّكَاةِ نَسَمَةً يَعْتِقُهَا بِجَرِّ وَلَاءٍ. وَهُوَ قَوْلُ الشَّافِعِيِّ وَأَصْحَابِ الرَّأْيِ وَرِوَايَةٍ عَنْ مَالِكٍ."],["tabari",9,60,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك عندي، قولُ من قال: \"عنى بالرقاب، في هذا الموضع، المكاتبون\"، لإجماع الحجة على ذلك، فإن الله جعل الزكاة حقًّا واجبًا على من أوجبها عليه في ماله، يخرجها منه، لا يرجع إليه منها نفعٌ من عرض الدنيا، ولا عِوَض. والمعتق رقبةً منها، راجع إليه ولاء من أعتقه، وذلك نفع يعود إليه منها."]],"l":[["saadi",2,270,"لطيفة واستنباط","ومضمون الإخبار بعلمه يدل على الجزاء وأن الله لا يضيع عنده مثقالُ ذرة، ويعلم ما صدرت عنه من نيات صالحة أو سيئة، وأن الظالمين الذين يمنعون ما أوجب الله عليهم، أو يقتحمون ما حرم عليهم، ليس لهم من دونه أنصار ينصرونهم ويمنعونهم."],["saadi",2,270,"لطيفة واستنباط","وأنه لا بد أن تقع بهم العقوبات، وأخبر أن الصدقة إن أبداها المتصدق فهي خير، وإن أخفاها وسلمها للفقير كان أفضل، لأن الإخفاء على الفقير إحسان آخر، وأيضاً فإنه يدل على قوة الإخلاص."],["saadi",2,270,"لطيفة واستنباط","فأما إذا صرفت في مشروع خيري لم يكن في الآية ما يدل على فضيلة إخفائها، بل هنا قواعد الشرع تدل على مراعاة المصلحة، فربما كان الإظهار خيراً لحصول الأسوة والاقتداء وتنشيط النفوس على أعمال الخير."]]},{"id":"hajj","t":"الحج والعمرة","d":"الحج فريضة العمر لمن استطاع؛ وفي الآيات مناسكه وأشهره وأحكام الفدية والهدي والوقوف بعرفة وذكر الله عنده.","r":[[2,196,203],[3,97,97],[22,27,29]],"q":[["tabari",2,196,"ترجيح","قال أبو جعفر: وأولى القولين بالصواب قول من قال:\" ما استيسر من الهدي\" شاة. لأن الله جل ثناؤه إنما أوجب ما استيسر من الهدي، وذلك على كل ما تيسر للمهدي أن يهديه كائنا ما كان ذلك الذي يهدي. إلا أن يكون الله جل ثناؤه خص من ذلك شيئا، فيكون ما خص من ذلك خارجا من جملة ما احتمله ظاهر التنزيل، ويكون سائر الأشياء غيره مجزئا إذا أهداه المهدي بعد أن يستحق اسم\" هدي\"."],["qurtubi",2,197,"استنباط","الرَّابِعَةُ- اخْتُلِفَ فِي الْإِهْلَالِ بِالْحَجِّ غَيْرَ أَشْهُرِ الْحَجِّ، فَرُوِيَ عَنِ ابْنِ عَبَّاسٍ: مِنْ سُنَّةِ الْحَجِّ أَنْ يُحْرَمَ بِهِ فِي أَشْهُرِ الْحَجِّ. وَقَالَ عَطَاءٌ وَمُجَاهِدٌ وَطَاوُسٌ وَالْأَوْزَاعِيُّ: مَنْ أَحْرَمَ بِالْحَجِّ قَبْلَ أَشْهُرِ الْحَجِّ لَمْ يُجْزِهِ ذَلِكَ عَنْ حَجِّهِ وَيَكُونُ عُمْرَةً، كَمَنْ دَخَلَ فِي صَلَاةٍ قَبْلَ وَقْتِهَا فَإِنَّهُ لَا تُجْزِيهِ وَتَكُونُ نَافِلَةً، وَبِهِ قَالَ الشَّافِعِيُّ وَأَبُو ثَوْرٍ. وَقَالَ الْأَوْزَاعِيُّ: يَحِلُّ بِعُمْرَةٍ. وَقَالَ أَحْمَدُ بْنُ حَنْبَلٍ: هَذَا مَكْرُوهٌ، وَرُوِيَ عَنْ مَالِكٍ، وَالْمَشْهُورُ عَنْهُ جَوَازُ الْإِحْرَامِ بِالْحَجِّ فِي جَمِيعِ السَّنَةِ كُلِّهَا، وَهُوَ قَوْلُ أَبِي حَنِيفَةَ."],["tabari",2,197,"ترجيح","قال أبو جعفر: والصواب من القول في ذلك عندنا، قول من قال: إن معنى ذلك: الحج شهران وعشر من الثالث؛ لأن ذلك من الله خبر عن ميقات الحج، ولا عمل للحج يعمل بعد انقضاء أيام منى، فمعلوم أنه لم يعن بذلك جميع الشهر الثالث، وإذا لم يكن معنيا به جميعه، صح قول من قال: وعشر ذي الحجة."]],"l":[["saadi",2,197,"لطيفة واستنباط","واستدل بهذه الآية الشافعي ومن تابعه على أنه لا يجوز الإحرام بالحج قبل أشهره، قلت: لو قيل [أنّ] فيها دلالة لقول الجمهور بصحة الإحرام بالحج قبل أشهره لكان قريباً، فإن قوله:{فمن فرض فيهن الحج}؛ دليل على أن الفرض قد يقع في الأشهر المذكورة، وقد لا يقع فيها وإلا لم يقيده، وقوله:{فلا رفث ولا فسوق ولا جدال في الحج}؛ أي: يجب أن تعظموا الإحرام بالحج وخصوصاً الواقع في أشهره، وتصونوه عن كل ما يفسده أو ينقصه من الرفث وهو الجماع، ومقدماته الفعلية والقولية، خصوصاً عند النساء بحضرتهن، والفسوق وهو جميع المعاصي، ومنها محظورات الإحرام، والجدال وهو المماراة والمنازعة والمخاصمة، لكونها تثير الشر وتوقع العداوة"],["ibnkathir",2,197,"فائدة","وَفَائِدَةُ مَذْهَبِ مَالِكٍ أنَّه إِلَى آخِرِ ذِي الْحِجَّةِ، بِمَعْنَى أَنَّهُ مُخْتَصٌّ بِالْحَجِّ، فيكره الاعتمار في بقية ذِي الْحِجَّةِ، لَا أَنَّهُ يَصِحُّ الْحَجُّ بَعْدَ لَيْلَةِ النَّحْرِ."],["saadi",2,197,"لطيفة واستنباط","واعلم أنه لا يتم التقرب إلى الله بترك المعاصي حتى يفعل الأوامر، ولهذا قال تعالى:{وما تفعلوا من خير يعلمه الله}؛ أتى بمن لتنصيص العموم فكل خير وقربة وعبادة داخل في ذلك، أي: فإن الله به عليم، وهذا يتضمن غاية الحث على أفعال الخير خصوصاً في تلك البقاع الشريفة والحرمات المنيفة، فإنه ينبغي تدارك ما أمكن تداركه فيها من صلاة وصيام وصدقة وطواف وإحسان قولي وفعلي، ثم أمر تعالى بالتزود لهذا السفر المبارك؛ فإن التزود فيه الاستغناء عن المخلوقين، والكف عن أموالهم سؤالاً واستشرافاً، وفي الإكثار منه نفع، وإعانة للمسافرين، وزيادة قربة لرب العالمين، وهذا الزاد الذي المراد منه إقامة البِنْية بُلْغَةٌ ومتاع"]]},{"id":"nikah","t":"النكاح والطلاق","d":"الآيات تنظّم الزواج والمعاشرة بالمعروف والطلاق والعدّة والرجعة، وتحفظ حقوق المرأة والأولاد وتحذّر من الظلم.","r":[[4,3,3],[2,228,232],[65,1,2],[4,19,21]],"q":[["tabari",4,3,"ترجيح","قال أبو جعفر: وأولى الأقوال التي ذكرناها في ذلك بتأويل الآية، قول من قال: تأويلها:\"وإن خفتم ألا تقسطوا في اليتامى، فكذلك فخافوا في النساء، فلا تنكحوا منهن إلا ما لا تخافون أن تجورُوا فيه منهن، من واحدة إلى الأربع، فإن خفتم الجورَ في الواحدة أيضًا، فلا تنكحوها، ولكن عليكم بما ملكت أيمانكم، فإنه أحرى أن لا تجوروا عليهن\"."],["qurtubi",2,229,"نظر واستنباط","قُلْتُ: وَهُوَ مَذْهَبُ مَالِكٍ وَالشَّافِعِيِّ وَأَحْمَدَ وَإِسْحَاقَ وَالثَّوْرِيِّ وَأَهْلِ الْكُوفَةِ. قَالَ التِّرْمِذِيُّ: وَأَكْثَرِ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ ﷺ وَغَيْرِهِمْ. قُلْتُ: وَحَدِيثُ ابْنِ عَبَّاسٍ فِي الْحَيْضَةِ مَعَ غَرَابَتِهِ كَمَا ذَكَرَ التِّرْمِذِيُّ، وَإِرْسَالِهِ كَمَا ذَكَرَ أَبُو دَاوُدَ فَقَدْ قِيلَ فِيهِ: إِنَّ النَّبِيَّ ﷺ جَعَلَ عِدَّتَهَا حَيْضَةً وَنِصْفًا، أَخْرَجَهُ الدَّارَقُطْنِيُّ مِنْ حَدِيثِ مَعْمَرٍ عَنْ عَمْرِو بْنِ مُسْلِمٍ عَنْ عِكْرِمَةَ عن ابن عباس: أن امرأة ثابت ابن قَيْسٍ اخْتَلَعَتْ مِنْ زَوْجِهَا فَجَعَلَ النَّبِيُّ ﷺ عِدَّتَهَا حَيْضَةً وَنِصْفًا."],["tabari",2,232,"ترجيح","قال أبو جعفر: والصواب من القول في هذه الآية أن يقال: إن الله تعالى ذكره أنزلها دلالة على تحريمه على أولياء النساء مضارة من كانوا له أولياء من النساء، بعضلهن عمن أردن نكاحه من أزواج كانوا لهن، فبن منهن بما تبين به المرأة من زوجها من طلاق أو فسخ نكاح. وقد يجوز أن تكون نزلت في أمر معقل بن يسار وأمر أخته، أو في أمر جابر بن عبد الله وأمر ابنة عمه. وأي ذلك كان، فالآية دالة على ما ذكرت."]],"l":[["saadi",4,3,"لطيفة واستنباط","وفيه دليل على أن للمرأة التصرف في مالها ولو بالتبرع إذا كانت رشيدةً؛ فإن لم تكن كذلك؛ فليس لعطيَّتِها حكم، وأنه ليس لوليها من الصداق شيء غير ما طابت به."],["saadi",4,3,"لطيفة واستنباط","وفي قوله:{فانكحوا ما طاب لكم من النساء}: دليلٌ على أن نكاح الخبيثة غير مأمور به، بل منهيٌّ عنه كالمشركة وكالفاجرة؛ كما قال تعالى:{ولا تنكحوا المشركات حتى يؤمنَّ}، وقال:{الزانية لا ينكحها إلا زانٍ أو مشركٌ}."],["saadi",4,3,"لطيفة واستنباط","ثم ذكر العدد الذي أباحه من النساء، فقال:{مثنى وثلاث ورباع}، أي: من أحب أن يأخذ ثنتين؛ فليفعل، أو ثلاثاً؛ فليفعل، أو أربعاً؛ فليفعل، ولا يزيد عليها؛ لأن الآية سيقت لبيان الامتنان؛ فلا يجوز الزيادة على غير ما سمى الله تعالى إجماعاً، وذلك لأن الرجل قد لا تندفع شهوتُه بالواحدة، فأبيح له واحدة بعد واحدة، حتى تبلغ أربعاً؛ لأن في الأربع غُنيةً لكل أحد إلا ما ندر، ومع هذا؛ فإنما يباح له ذلك إذا أمن على نفسه الجَوْر والظلم ووثق بالقيام بحقوقهن؛ فإن خاف شيئاً من هذا؛ فليقتصر على واحدة أو على ملك يمينه؛ فإنه لا يجب عليه القَسْم في ملك اليمين، {ذلك}"]]},{"id":"muamalat","t":"المعاملات والعقود","d":"تحريم الربا وأحكام الدَّين والكتابة والشهادة والرهن، والأمر بالوفاء بالعقود، وأكل المال بالتراضي لا بالباطل.","r":[[2,275,282],[4,29,29],[5,1,1]],"q":[["tabari",4,29,"ترجيح","قال أبو جعفر: وأولى القولين بالصواب في ذلك عندنا، قولُ من قال: إن التجارة التي هي عن تراض بين المتبايعين، ما تفرّق المتبايعان عن المجلس الذي تواجبَا فيه بينهما عُقدة البيع بأبدانهما، عن تراض منهما بالعقد الذي جرى بينهما، وعن تخيير كل واحد منهما صاحبه = لصحة الخبر عن رسول الله ﷺ، بما:-"],["qurtubi",2,282,"استنباط","الثَّالِثَةُ- قَوْلُهُ تَعَالَى: ﴿إِلى أَجَلٍ مُسَمًّى﴾ قَالَ ابْنُ الْمُنْذِرِ: دَلَّ قَوْلُ اللَّهِ \"إِلى أَجَلٍ مُسَمًّى\" عَلَى أَنَّ السَّلَمَ إِلَى الْأَجَلِ الْمَجْهُولِ غَيْرُ جَائِزٍ، وَدَلَّتْ سُنَّةِ رَسُولِ اللَّهِ ﷺ عَلَى مِثْلِ مَعْنَى كِتَابِ اللَّهِ تَعَالَى. ثَبَتَ أَنَّ رَسُولَ اللَّهِ ﷺ قَدِمَ الْمَدِينَةَ وَهُمْ يَسْتَلِفُونَ فِي الثِّمَارِ السَّنَتَيْنِ وَالثَّلَاثَ، فَقَالَ رَسُولُ اللَّهِ ﷺ: \"مَنْ أَسْلَفَ فِي تَمْرٍ فَلْيُسْلِفْ فِي كَيْلٍ مَعْلُومٍ وَوَزْنٍ مَعْلُومٍ إِلَى أَجَلٍ مَعْلُومٍ\" رَوَاهُ ابْنُ عَبَّاسٍ. أَخْرَجَهُ الْبُخَارِيُّ وَمُسْلِمٌ وَغَيْرُهُمَا. وَقَالَ ابْنُ عُمَرَ: كَانَ أَهْلُ الْجَاهِلِيَّةِ يَتَبَايَعُونَ لَحْمَ الْجَزُورِ إِلَى حَبَلِ الْحَبَلَةِ. وَحَبَلُ الْحَبَلَةِ: أَنْ تُنْتَجَ النَّاقَةُ ثُمَّ تَحْمِلُ الَّتِي نُتِجَتْ."],["tabari",5,1,"ترجيح","قال أبو جعفر: وأولى الأقوال في ذلك عندنا بالصواب، ما قاله ابن عباس، وأن معناه: أوفوا، يا أيها الذين آمنوا، بعقود الله التي أوجبَهَا عليكم، وعقدها فيما أحلَّ لكم وحرم عليكم، وألزمكم فرضه، وبيَّن لكم حدوده."]],"l":[["saadi",2,282,"لطيفة واستنباط","وفيها: التنبيه على أن جميع المحسنين الفاعلين للمعروف لا يحل إضرارهم وتحميلهم ما لا يطيقون، فهل جزاء الإحسان إلا الإحسان؟ وكذلك على من أحسن وفعل معروفاً أن يتمم إحسانه بترك الإضرار القولي والفعلي بمن أوقع به المعروف، فإن الإحسان لا يتم إلا بذلك."],["saadi",2,282,"لطيفة واستنباط","ومنها: أن الكتابة بين المتعاملين من أفضل الأعمال ومن الإحسان إليهما، وفيها حفظ حقوقهما وبراءة ذممهما كما أمره الله بذلك فليحتسب الكاتب بين الناس هذه الأمور ليحظى بثوابها."],["saadi",2,282,"لطيفة واستنباط","ومنها: التنبيه على المصالح والفوائد المترتبة على العمل بهذه الإرشادات الجليلة وأن فيها حفظ الحقوق والعدل وقطع التنازع والسلامة من النسيان والذهول ولهذا قال: {ذلكم أقسط عند الله وأقوم للشهادة وأدنى ألا ترتابوا}؛ وهذه مصالح ضرورية للعباد."]]},{"id":"hudud","t":"القصاص والحدود","d":"القصاص في القتل حياة للمجتمع، وحدّ السرقة والزنا؛ وآياتها تقرن العقوبة بالعفو والرحمة وحفظ الضرورات الخمس.","r":[[2,178,179],[5,38,38],[24,2,2],[5,45,45]],"q":[["tabari",24,2,"ترجيح","وأولى القولين في ذلك بالصواب قول من قال: معنى ذلك: ولا تأخذكم بهما رأفة في إقامة حدّ الله عليهما الذي افترض عليكم إقامته عليهما."],["qurtubi",24,2,"استنباط","الرَّابِعَةَ عَشْرَةَ- الضَّرْبُ الَّذِي يَجِبُ هُوَ أَنْ يَكُونَ مُؤْلِمًا لَا يَجْرَحُ وَلَا يُبْضِعُ، وَلَا يُخْرِجُ الضَّارِبُ يَدَهُ مِنْ تَحْتِ إِبْطِهِ. وَبِهِ قَالَ الْجُمْهُورُ، وَهُوَ قَوْلُ عَلِيٍّ وَابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُمَا. وَأُتِيَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ بِرَجُلٍ فِي حَدٍّ فَأُتِيَ بِسَوْطٍ بَيْنَ سَوْطَيْنِ وَقَالَ لِلضَّارِبِ: اضْرِبْ وَلَا يُرَى إِبْطُكُ، وَأَعْطِ كُلَّ عُضْوٍ حَقَّهُ. وَأُتِيَ رَضِيَ اللَّهُ عَنْهُ بِشَارِبٍ فَقَالَ: لَأَبْعَثَنَّكَ إِلَى رَجُلٍ لَا تَأْخُذُهُ فِيكَ هَوَادَةٌ، فَبَعَثَهُ إِلَى مُطِيعِ بْنِ الْأَسْوَدِ الْعَدَوِيِّ فَقَالَ: إِذَا أَصْبَحْتَ الْغَدَ فَاضْرِبْهُ الْحَدَّ، فَجَاءَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ وَهُوَ يَضْرِبُهُ ضَرْبًا شَدِيدًا فَقَالَ: قَتَلْتَ الرَّجُلَ! كَمْ ضَرَبْتَهُ؟"],["tabari",24,2,"ترجيح","وأولى الأقوال في ذلك بالصواب قول من قال: أقل ما ينبغي حضور ذلك من عدد المسلمين: الواحد فصاعدًا؛ وذلك أن الله عمّ بقوله: ﴿وَلْيَشْهَدْ عَذَابَهُمَا طَائِفَةٌ﴾ والطائفة: قد تقع عند العرب على الواحد فصاعدا."]],"l":[["saadi",2,178,"لطيفة واستنباط","وفي هذه الآية دليل على أن الأصل وجوب القود في القتل وأن الدية بدل عنه، فلهذا قال:{فمن عفي له من أخيه شيء}؛ أي: عفا ولي المقتول عن القاتل إلى الدية أو عفا بعض الأولياء فإنه يسقط القصاص وتجب الدية وتكون الخيرة في القود واختيار الدية إلى الولي، فإذا عفا عنه، وجب على الولي؛ أي ولي المقتول أن يتبع القاتل، {بالمعروف}؛ من غير أن يشق عليه ولا يحمله ما لا يطيق، بل يحسن الاقتضاء والطلب ولا يحرجه."],["saadi",2,178,"لطيفة واستنباط","ثم بين تفصيل ذلك فقال:{الحر بالحر}؛ يدخل بمنطوقها الذكر بالذكر، والأنثى بالأنثى؛ والأنثى بالذكر والذكر بالأنثى، فيكون منطوقها مقدماً على مفهوم قوله الأنثى بالأنثى مع دلالة السنة على أن الذكر يقتل بالأنثى، وخرج من عموم هذا الأبوان وإن علوا فلا يقتلان بالولد لورود السنة بذلك مع أن في قوله:{القصاص}؛ ما يدل على أنه ليس من العدل أن يقتل الوالد بولده ولأن ما في قلب الوالد من الشفقة والرحمة ما يمنعه من القتل لولده إلا بسبب اختلال في عقله أو أذية شديدة جدًّا من الولد له، وخرج من العموم أيضاً الكافر بالسنة مع أن الآية في خطاب المؤمنين خاصة، وأيضاً فليس من العدل أن يقتل ولي الله بعدوه، {والعبد بالعبد}"],["saadi",2,178,"لطيفة واستنباط","ونكر الحياة لإفادة التعظيم والتكثير، ولما كان هذا الحكم لا يعرف حقيقته إلا أهل العقول الكاملة والألباب الثقيلة خصهم بالخطاب دون غيرهم، وهذا يدل على أن الله تعالى يحب من عباده أن يعملوا أفكارهم وعقولهم في تدبر ما في أحكامه من الحكم والمصالح الدالة على كماله وكمال حكمته وحمده وعدله ورحمته الواسعة، وأن من كان بهذه المثابة فقد استحقَّ المدح بأنه من ذوي الألباب الذين وجه إليهم الخطاب وناداهم رب الأرباب، وكفى بذلك فضلاً وشرفاً لقوم يعقلون."]]},{"id":"at3ima","t":"الأطعمة والأشربة","d":"ما أحلّ الله من الطيبات وما حرّم من الخبائث (الميتة والدم ولحم الخنزير وما أهلّ به لغير الله)، وأحكام الذبائح وطعام أهل الكتاب.","r":[[5,3,5],[2,172,173],[6,145,145]],"q":[["qurtubi",5,3,"نظر واستنباط","قُلْتُ: الْحَدِيثُ الَّذِي أَشَارَ إِلَيْهِ أَخْرَجَهُ الدَّارَقُطْنِيُّ مِنْ حَدِيثِ أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ وَعَلِيٍّ وَعَبْدِ اللَّهِ عَنِ النَّبِيِّ ﷺ قَالَ: (ذَكَاةُ الْجَنِينِ ذَكَاةُ أُمِّهِ). وَبِهِ يَقُولُ جَمَاعَةُ أَهْلِ الْعِلْمِ، إِلَّا مَا رُوِيَ عَنْ أَبِي حَنِيفَةَ أَنَّهُ قَالَ: إِذَا خَرَجَ الْجَنِينُ مِنْ بَطْنِ أُمِّهِ مَيِّتًا لَمْ يَحِلَّ أَكْلُهُ، لِأَنَّ ذَكَاةَ نَفْسٍ لَا تَكُونُ ذَكَاةَ نَفْسَيْنِ."],["tabari",5,4,"ترجيح","قال أبو جعفر: وأولى القولين بتأويل الآية قول من قال:\"كل ما صاد من الطير والسباع فمن الجوارح، وأنّ صيد جميع ذلك حلال إذا صادَ بعد التعليم\"، لأن الله جل ثناؤه عم بقوله:\"وما علمتم من الجوارح مكلبين\"، كلَّ جارحة، ولم يخصص منها شيئًا. فكل\"جارحة\"، كانت بالصفة التي وصف الله من كل طائر وسبع، فحلال أكل صيدها."],["qurtubi",5,3,"نظر واستنباط","قُلْتُ: أَجَابَ عُلَمَاؤُنَا عَنْ حَدِيثِ رَافِعِ بْنِ خَدِيجٍ بِأَنْ قَالُوا: تَسْلِيطُ النَّبِيِّ ﷺ إِنَّمَا هُوَ عَلَى حَبْسِهِ لَا عَلَى ذَكَاتِهِ، وَهُوَ مُقْتَضَى الْحَدِيثِ وَظَاهِرِهِ، لِقَوْلِهِ: (فَحَبَسَهُ) وَلَمْ يَقُلْ إِنَّ السَّهْمَ قَتَلَهُ، وَأَيْضًا فَإِنَّهُ مَقْدُورٌ عَلَيْهِ فِي غَالِبِ الْأَحْوَالِ فَلَا يُرَاعَى النَّادِرُ مِنْهُ، وَإِنَّمَا يَكُونُ ذَلِكَ فِي الصَّيْدِ. وَقَدْ صَرَّحَ الْحَدِيثُ بِأَنَّ السَّهْمَ حَبَسَهُ وَبَعْدَ أَنْ صَارَ مَحْبُوسًا صَارَ مَقْدُورًا عَلَيْهِ، فَلَا يُؤْكَلُ إِلَّا بِالذَّبْحِ وَالنَّحْرِ. وَاللَّهُ أَعْلَمُ. وَأَمَّا حَدِيثُ أَبِي الْعُشَرَاءِ فَقَدْ قَالَ فِيهِ التِّرْمِذِيُّ: \"حَدِيثٌ غَرِيبٌ لَا نَعْرِفُهُ إِلَّا مِنْ حَدِيثِ حَمَّادِ بْنِ سَلَمَةَ، وَلَا نَعْرِفُ لِأَبِي الْعُشَرَاءِ عَنْ أَبِيهِ غَيْرَ هَذَا الْحَدِيثِ."]],"l":[["saadi",5,3,"لطيفة واستنباط","وقوله:{إلَّا ما ذَكَّيۡتُم}: راجعٌ لهذه المسائل من منخنقةٍ وموقوذةٍ ومتردِّيةٍ ونطيحةٍ وأكيلة سبع إذا ذُكِّيت وفيها حياةٌ مستقرَّة لتتحقق الذَّكاة فيها."],["saadi",5,4,"لطيفة واستنباط","دلَّت هذه الآية على أمور: أحدها: لطف الله بعبادِهِ ورحمته لهم حيثُ وسَّع عليهم طرق الحلال، وأباح لهم ما لم يُذَكُّوه مما صادته الجوارح، والمراد بالجوارح الكلاب والفهود والصقر ونحو ذلك مما يصيد بنابه أو بمخلبه."],["saadi",5,4,"لطيفة واستنباط","العاشر: أنه يجوز أكل ما صاده الجارح، سواء قتله الجارح أم لا، وأنه إن أدركه صاحبه وفيه حياة مستقرة؛ فإنه لا يباح إلا بها."]]}]}];
